/* Human Matrix 0.11 — channels and gates deepened from Bunnell / Ra Uru Hu,
 * «Дизайн Человека. Наука о Дифференциации», section 6 and section 10 (line names).
 * Texts are written independently; only canonical names and line names follow the book.
 */
(() => {
  const SOURCE='Баннелл, «Наука о Дифференциации»';
  const CHANNEL_BOOK={"1-8": {"name": "Канал Вдохновения", "design": "Дизайн Творческой ролевой модели", "type": "Проецируемый", "page": 178, "classic": "Канал Вдохновения тянется от G-центра, где живут идентичность и направление, к Горлу — центру выражения: 1-е ворота Самовыражения встречаются здесь с 8-ми воротами Вклада. В Дизайне Человека это «Дизайн Творческой ролевой модели», творческий канал Контура Знания внутри Индивидуальной группы, чья главная тема — мутация и усиление. Книга сравнивает его с авансценой, на которую выходят творческий и лидерский потенциал контура. Голос канала звучит так: «Я знаю, что могу (или не могу) сделать творческий вклад». Такой человек меняет мир не доводами, а тем, что целиком проживает собственную уникальность и показывает новое направление своим примером. Канал проецируемый: его сила раскрывается, когда индивидуальность замечают и признают другие, а при связи с мотором — например, через 2-14 — вклад становится ещё весомее.", "inner": "Дар этого канала — быть живым образцом: как пианист, после концерта которого кто-то из слушателей идёт учиться музыке. Опора здесь — собственная правда и настоящий момент, а внутренний ориентир — красота. Книга подчёркивает, что пример стоит чего-то, только когда он вырастает из подлинного Внутреннего Авторитета, а не из случайных влияний извне; иначе человек вдохновляет «чужим» образом себя. Типичная трудность — нехватка социальных навыков, из-за которой попытки прорваться к людям через слова и общение выходят неловкими; здесь нужно терпение и умение дождаться своего времени. Расцвет приходит через признание и принятие собственной непохожести — сначала самим человеком, а затем и окружающими.", "together": "В группе такие люди работают как сеятели нового: своим способом жить они побуждают других пересмотреть взгляды на правду, красоту и собственный путь. Они не уговаривают — им достаточно быть заметными. Живя свою уникальность щедро и открыто, они косвенно дают окружающим разрешение тоже быть непохожими.", "plain": "Вы влияете на людей не советами, а тем, как живёте сами. Когда вы занимаетесь своим делом по-своему и с любовью, это вдохновляет других искать свой путь. Не торопитесь доказывать свою ценность словами — лучше дождаться, когда вас заметят и позовут.", "practice": ["В какие моменты люди сами говорили, что вы их чем-то вдохновили, — и что вы тогда на самом деле делали?", "Когда вы пытаетесь привлечь внимание к своему делу словами и убеждением, как это обычно складывается по сравнению с ситуациями, когда вас замечают сами?"]}, "2-14": {"name": "Канал Биения", "design": "Дизайн Хранителя ключей", "type": "Генерируемый", "page": 176, "classic": "Сакральный центр, источник чистой жизненной энергии, соединяется здесь с G-центром идентичности и направления: 14-е ворота Силовых навыков подают ресурс, 2-е ворота Высшего знания задают курс. Книга называет 2-е ворота «креслом Водителя», где находится Магнитный Монополь, связывающий нас и ведущий сквозь пространство и время. Канал Биения — один из трёх тантрических каналов между Сакралом и G и единственный индивидуальный среди них, поэтому несёт все краски Индивидуальности: новизну, неординарность, мутацию и меланхолию. Отсюда образ «Хранителя ключей» — того, у кого под рукой есть всё, чтобы превратить импульс перемен в материальное направление. Канал генерируемый: его энергия включается через Сакральный отклик, а не через заранее составленный план. Мутация здесь пульсирует — отклик то есть, то его нет, и заранее не узнать, когда установится новое направление.", "inner": "В Дизайне Человека этот человек способен давать новое усиливающее направление людям, проектам и даже большим делам, просто доверяя своему Сакральному отклику и не зная наперёд, куда тот приведёт. Он может вкладывать ресурсы в собственное творчество или поддерживать чужое — и деньгами, и вдохновением. Первая задача — быть верным себе и жить свою судьбу, а не гоняться за ней: погоня, по книге, приносит лишь потерянность и разочарование. Корректное проживание описано как открытость и отзывчивость к жизни, когда решения как будто принимаются через человека, а не им самим. Тогда он механически усиливает окружающих, а люди в его ауре получают возможность почувствовать вкус собственного направления.", "together": "Коллектив и Племя держатся за безопасность и привычный порядок, а носитель 2-14 приносит им ключ к новым путям. Со временем окружающие проверяют предложенное и берут на вооружение самое практичное. Рядом с таким человеком другие нередко ощущают, куда двигаться им самим, — без всяких наставлений с его стороны.", "plain": "У вас есть сила и ресурсы, чтобы направить себя и других в новую сторону, но работает это лучше всего, когда вы откликаетесь на то, что приходит в жизнь, а не продавливаете план. Иногда ясность о направлении есть, иногда её нет — это нормально. Когда вы следуете своему внутреннему «да», люди рядом начинают лучше чувствовать свой путь.", "practice": ["Вспомните решение, после которого ваша жизнь или чей-то проект резко сменили курс: оно родилось из плана или из мгновенного внутреннего «да»?", "Как вы обычно переживаете периоды, когда нового направления не видно, — ждёте или начинаете искать его усилием?"]}, "3-60": {"name": "Канал Мутации", "design": "Дизайн Инициирующей и переменчивой энергии — Пульс", "type": "Генерируемый", "page": 174, "classic": "Между Корневым центром с его давлением и Сакралом с его жизненной силой проходит Канал Мутации: 60-е ворота Принятия вмещают все эволюционные возможности, а 3-и ворота Упорядочивания вытаскивают из них что-то одно новое и жизнеспособное. Это форматная энергия Индивидуального контура — такие каналы связывают Корень и Сакрал, окрашивают весь контур и, по книге, влияют на весь дизайн человека (у Племени форматного канала нет). Пульс «вкл/выкл», адреналин и сопутствующая меланхолия задают ритм всей жизни носителя и заметно сказываются на окружающих. Тема канала — бесконечное движение от хаоса к порядку и обратно, из которого рождается новое. Канал генерируемый, поэтому мутация становится полезной, когда её запускает Сакральный отклик. Его потенциал зависит от готовности принять ограничения и вынести трудности новых начинаний.", "inner": "Главный ключ, который даёт книга, — не искать умственных объяснений перепадам настроения и меланхолии, а терпеливо и внимательно ждать следующего импульса. Время «выключенного» пульса можно прожить наедине со своей музой: внутри что-то вызревает, даже если это пока незаметно. Ловушка — пытаться найти причину грусти, уходить в «тень» или действовать без корректного отклика: тогда давление менять жизнь превращается в личное расстройство и уныние, а вокруг — в нестабильность. Корректное проживание описано как принятие главного ограничения — незнания, когда случится пульс, — и доверие Сакральному отклику. Этого достаточно, чтобы человек принёс в мир свой «ветер перемен».", "together": "Мутация здесь похожа на музыкальную импровизацию: она возникает неожиданно, в паузе между пульсациями, и ставит окружающих перед выбором — меняться вместе или остаться позади. Носители канала ощущают давление обновлять работу, семью, привычный уклад. Когда они ждут отклика, перемены приходят вовремя; когда торопят их, близкие переживают это как хаос.", "plain": "В вашей жизни есть периоды подъёма и периоды затишья, когда ничего не происходит и бывает грустно. Это не поломка, а ваш естественный ритм: в паузах зреет новое. Перемены, которые вы приносите, лучше всего удаются, когда приходят сами и вы на них откликаетесь, а не устраиваете их через силу.", "practice": ["Что вы обычно делаете, когда накатывает беспричинная грусть: ищете объяснение или позволяете ей быть?", "Вспомните перемену, которая случилась у вас внезапно и оказалась удачной: что ей предшествовало — затишье или активные поиски?"]}, "4-63": {"name": "Канал Логики", "design": "Дизайн Ментальной легкости, смешанной с сомнениями", "type": "Проецируемый", "page": 212, "classic": "«Сомневающийся ум» — так можно коротко описать Канал Логики, соединяющий Теменной центр вдохновения и давления с Аджной, центром осмысления. 63-и ворота Сомнения задают вопрос, 4-е ворота Формулирования ищут ответ. Это часть Контура Понимания в Коллективной группе: логика смотрит в будущее и проверяет, насколько надёжен паттерн, ведь безупречная формула всё равно может оказаться неверной. Скепсис здесь — форма страха, которая живёт между вопросом и ответом, и ответ остаётся «всего лишь ответом», пока не подтвердится на практике. Книга приводит пример: человек с этим каналом может не принять даже саму Систему Дизайна Человека, пока не проверит её на себе. Канал проецируемый и не связан с мотором, поэтому его ценность раскрывается, когда вопросы и формулы востребованы другими.", "inner": "В Дизайне Человека этот ум принимает жизнь со здоровым скептицизмом — прикидывает, например, вероятность дождя на следующей неделе. Он силён в постановке вопросов, ищет закономерности в текущих данных и строит прогнозы на благо общего: «защитит ли это нас завтра?». Есть порыв сразу поделиться и вопросом, и ответом; полезно сначала понять, интересно ли это слушателям. Когда вопрос не находит разрешения, давление превращается в беспокойство. Книга подчёркивает: этот канал коллективный, и собственные жизненные сомнения и тревоги о своём будущем ему решать не дано — такому уму лучше дать другую пищу.", "together": "Как электромагнит между двумя людьми этот канал даёт, по книге, самую благоприятную ментальную связь: обладатель 63-х ворот приносит сомнения, обладатель 4-х — решения. Лучше всего, когда оба понимают, что радость в самом обмене, и не ждут от партнёра непременно полезных ответов или исключительно ценных вопросов. Подходящий момент для такого разговора подсказывают Стратегия и Авторитет.", "plain": "Вы склонны во всём сомневаться и проверять, пока не убедитесь, что это действительно работает. Это ценное качество для общих дел и прогнозов, но плохой инструмент для решения личных тревог о будущем. Делитесь вопросами и идеями, когда людям это интересно, — тогда это приносит удовольствие и вам, и им.", "practice": ["Какие вопросы крутятся у вас в голове чаще всего — про общие дела и мир или про собственное будущее? Что вы чувствуете в каждом случае?", "Вспомните разговор, где обмен вопросами и ответами доставил удовольствие обоим: как он начался?"]}, "5-15": {"name": "Канал Ритма", "design": "Дизайн Пребывания в потоке", "type": "Генерируемый", "page": 204, "classic": "Книга называет Канал Ритма краеугольным камнем биологической жизни: через него человек подключён к универсальному ритму, общему для всех форм жизни — от клетки до человека. Он соединяет Сакральный центр с G-центром: 5-е ворота держатся за фиксированные привычки и ритуалы, 15-е ворота Крайностей с любовью к человеческому многообразию собирают разных людей в общий поток. Это один из трёх тантрических каналов между Сакралом и G и часть Контура Понимания: ритм здесь логичен, он строится на повторяющихся, но развивающихся паттернах и ведёт всех в будущее. Магнетизм 15-х ворот описан как проекция безличной, универсальной любви Магнитного Монополя к человечеству. Канал генерируемый — с ритмом он соединяет через каждый Сакральный отклик, а не через ум или эмоциональную волну. Отсюда его название: «Дизайн Пребывания в потоке».", "inner": "Со стороны такой человек плывёт по «реке жизни» в собственном темпе, и другие видят, что его чувство времени задано изнутри. В Дизайне Человека считается, что если его привычный распорядок естественен и корректен, ничему не стоит позволять в него вмешиваться. Настроиться на природный ритм можно только действуя из отклика: тайминг выставляет Сакрал, а не голова. В своём потоке всё идёт без сопротивления и незаметно помогает другим попасть в собственный ритм. Ловушка — тайминг «ложного я»: тогда сбивается и свой ритм, и чужой, а жизнь вокруг становится суетливой и бестолковой.", "together": "Аура канала втягивает людей в устойчивый, но гибкий поток, позволяющий двигаться вперёд безопасно; идеал книги — разобусловленные люди, идущие рядом на равных. Как электромагнит между двумя людьми 5 и 15 бывают непростой парой: одному нужен постоянный ритм, другому — свобода крайностей. Зато вместе они задают течение, которому начинает следовать вся группа.", "plain": "У вас свой внутренний темп и свой распорядок, и когда вы ему следуете, всё складывается легко. Попытки жить по чужому расписанию или подгонять себя обычно сбивают и вас, и людей вокруг. Прислушивайтесь к тому, на что тело отзывается «да», — так вы попадаете в свой поток.", "practice": ["Какие привычки или ритуалы дают вам ощущение, что день «течёт» сам, а какие вы держите через силу?", "Что происходит с вашим самочувствием и с окружающими, когда кто-то сбивает вас с привычного темпа?"]}, "6-59": {"name": "Канал Интимности", "design": "Дизайн, сфокусированный на воспроизводстве", "type": "Генерируемый", "page": 236, "classic": "Канал Интимности книга называет ядром творческой сути человека: в нём сходятся мощная энергия Сакрала и эмоциональная энергия Солнечного Сплетения. 59-е ворота Сексуальности стремятся к соединению, а 6-е ворота Трения с волной удовольствия и боли регулируют близость, сближая или отдаляя. Это Племенной канал Контура Защиты, где тема поддержки принимает форму генетического импульса «произвести больше» — продолжить жизнь, будь то ребёнок, бизнес или совместное творчество. Канал генерируемый, но определённое Солнечное Сплетение всегда становится Авторитетом, поэтому ответ Сакрала нужно выдержать сквозь эмоциональную волну до ясности. Если каналом управляет спонтанное ложное «я», появляются запутанные отношения и долгие последствия — книга упоминает нежеланного ребёнка или неудачное партнёрство. Отсюда её совет: сначала дружба, потом глубокий союз.", "inner": "Когда желание соединиться ведёт созревший со временем отклик, связь получается здоровой и глубоко насыщающей. Открытость к близости позволяет такому человеку легко входить в чужие ауры и прокладывать дорогу плодотворности в любом совместном деле — это его естественный вклад в отношения любого рода. Типичная трудность — его интенсивность легко принимают за флирт или намёк, которого и в мыслях не было. Тайминг любой близости задаёт волна 6-х ворот: она то приближает, то отталкивает. Пережидая полный цикл волны, человек со временем узнаёт, рождается ли между двумя людьми что-то настоящее.", "together": "Внешне носители канала могут казаться очень спокойными: их волна часто активируется именно через близость или прикосновение другого. Вовремя сделанное объятие или похлопывание по плечу помогает выпустить то, что не выражается словами, — слёзы, глубокий вздох. Сильнее всего канал проживается как электромагнит, когда у двух людей по одним воротам.", "plain": "Вы легко сближаетесь с людьми, и ваше внимание порой воспринимают сильнее, чем вы задумывали. Чувства у вас приходят волнами, поэтому важные решения о близости и партнёрстве лучше принимать не сразу, а когда эмоции улягутся. Дружба как первый шаг — хороший способ проверить, что связь настоящая.", "practice": ["Бывало ли, что ваше дружелюбие или интерес к человеку поняли не так, как вы имели в виду? Что тогда происходило?", "Как менялось ваше отношение к новому партнёру или проекту за несколько дней и недель — и какое решение оказывалось вернее, первое или позднее?"]}, "7-31": {"name": "Канал Альфы", "design": "Дизайн Лидерства в «хорошем» или «плохом»", "type": "Проецируемый", "page": 206, "classic": "Название «Канал Альфы» отсылает к вожаку стаи, а подзаголовок звучит как «Дизайн Лидерства в „хорошем“ или „плохом“». Канал соединяет G-центр с Горлом: 7-е ворота Роли «Я» дают логическую роль направляющего общества — книга сравнивает её с «серым кардиналом», а 31-е ворота Лидерства дают голос влияния. Это часть Контура Понимания в Коллективной группе, поэтому лидерство здесь демократическое: оно смотрит в будущее и опирается на проверенные паттерны, за которыми можно идти. Альфе сначала нужно завоевать доверие — показать навыки, понимание тенденций и нужд людей, — и лишь затем большинство приглашает её вести. Канал проецируемый и не связан с мотором, поэтому его сила — во влиянии, а не в принуждении. Этим коллективный лидер отличается и от автократии Племени, и от личного примера Индивидуала.", "inner": "Книга приводит образ волчьей стаи: стаю не всегда ведёт альфа, но настоящий альфа не остаётся там, где правит другой. Человек с этим каналом может так и не стать публичной фигурой, но всё равно ищет свою сферу влияния — «свою стаю». Найдя её, он обращает внимание людей на то, что важно для движения в правильную сторону, показывая путь, но не проходя его за них. Ловушка — пытаться вести без приглашения или опираться на абсолютную власть. Ключ к успеху и собственному благополучию книга называет прямо: лидерство через влияние.", "together": "Альфа может сказать: «делайте так, и это сработает», но пока группа не выберет его сама, ничего не заработает. Шансы выше, когда он ждёт признания от тех, кто разделяет с ним общий контекст. Срок у руля зависит от того, как «электорат» оценивает результаты, а вызовы его решениям — часть движения к более надёжному будущему.", "plain": "Вам свойственно видеть, куда стоит двигаться группе, и хочется её вести. Это получается лучше всего, когда люди сами доверяют вам и просят взять руководство, а не когда вы его берёте. Ваша сила — подсказать направление, а не сделать всё за других.", "practice": ["В каких сообществах вас сами просили взять на себя руководство, а где вы брали его без приглашения? Чем отличались результаты?", "Как вы реагируете, когда группа оспаривает ваше предложение, которое вы считаете верным?"]}, "9-52": {"name": "Канал Концентрации", "design": "Дизайн Целеустремленности", "type": "Генерируемый", "page": 202, "classic": "Корневой центр с его давлением и Сакрал с его жизненной силой образуют здесь Канал Концентрации: 52-е ворота Неподвижности дают спокойное топливо, 9-е ворота Фокуса удерживают внимание на деталях и фактах. Это форматная энергия Контура Понимания — логического крыла Коллективной группы, которое смотрит в будущее и совершенствует паттерны. Как и другие форматные каналы между Корнем и Сакралом, он несёт качества всего своего контура и влияет на весь дизайн человека, помогая корректировать и улучшать любую форму или занятие. Логический процесс идёт шаг за шагом и требует достаточно долго оставаться с формулой, чтобы доказать или опровергнуть её. Канал генерируемый: энергия собрана и готова к делу, но направляет её Сакральный отклик. В подзаголовке книги — «Дизайн Целеустремлённости».", "inner": "Такой человек постоянно оценивает детали того, чему себя посвятил, и чувствует мягкое давление замереть и «оставаться на месте», как в позе йоги: тело неподвижно, внешний шум отходит, энергия тратится точно. Книга сравнивает это с Буддой под деревом Бодхи, копящим силу в ожидании отклика. Именно отклики подсказывают, какой паттерн совершенствовать дальше и когда делиться результатом; так раскрывается жизненный фокус — одно дело на годы или череда разных интересов. Ловушка — периоды, когда сосредоточиться не на чем и Авторитет ничему не говорит «да»: тогда возможны отчаяние и подавленность. В Дизайне Человека выход видят не в том, чтобы хвататься за что попало, а в терпеливом ожидании следующего отклика.", "together": "Аура канала как будто удерживает энергию в одной точке и помогает группе собраться и глубже копнуть текущий проект. Людям без этой определённости бывает полезно поработать рядом с его носителем, чтобы прибавить себе усидчивости.", "plain": "Вы умеете надолго погружаться в одно дело и замечать детали, которые другие пропускают. Лучше всего это работает, когда вы выбираете занятие по внутреннему отклику, а не из чувства долга. Если сосредоточиться пока не на чем, это может тяготить — стоит дождаться того, что по-настоящему зацепит.", "practice": ["Какое занятие удерживало ваше внимание дольше всего без усилия — и как вы к нему пришли?", "Как вы себя чувствуете в периоды, когда нет дела, на котором хочется сосредоточиться, и что обычно делаете в это время?"]}, "10-20": {"name": "Канал Пробуждения", "design": "Дизайн Приверженности высшим принципам", "type": "Проецируемый", "page": 168, "classic": "«Я есть! Я жив СЕЙЧАС!» — таков голос Канала Пробуждения, связывающего G-центр с Горлом. 10-е ворота Поведения «Я» несут глубинный код поведения, 20-е ворота Настоящего превращают индивидуальное знание в правильное действие в этот самый момент. Канал входит в Интеграцию — особую систему вне трёх больших групп, которую книга сравнивает с позвоночником бодиграфа и называет защитным механизмом формы с суперключом «самоусиление». Подзаголовок — «Дизайн Приверженности высшим принципам»; две опоры пробуждённой жизни здесь — любовь к себе и доверие к себе. Пробуждение в терминах Дизайна Человека — это принимать решения из своей природы и проживать их, каким бы обыденным ни был опыт. Канал проецируемый, поэтому его ясность особенно хорошо проявляется в ответ на приглашение и признание.", "inner": "G-центр не является центром осознанности, поэтому этот канал умеет только одно — говорить за себя. Если поведение человека становится живым примером любви к себе, принятия и доверия, он просто реализует себя, получает признание и узнаёт о себе по ходу жизни. Окружающие чувствуют в нём что-то ясное и осознанное, хотя сам он этого может не видеть; просто оставаясь собой, он вдохновляет других. Книга описывает это как своего рода видение, которое замечает фальшь в людях и помогает распознавать верные приглашения. Корректные приглашения, в свою очередь, оберегают от сопротивления, от болезненного восприятия критики и от тяжести непринятия своей уникальности.", "together": "Канал выступает лидерским голосом Интеграции: влияет не программой, а самим присутствием в настоящем. О стиле поведения подсказывают шесть линий 10-х ворот — от пробуждения через знание, как действовать в моменте, до примера, который будит людей больше делами, чем словами. Окружающие считывают его через поступки, общение и манеру держаться.", "plain": "Ваша сила в том, чтобы быть собой прямо сейчас и говорить от своего имени. Когда вы живёте по-своему и принимаете себя, люди рядом это чувствуют и тоже становятся смелее. Вам легче, когда вас приглашают высказаться, а не когда приходится пробиваться.", "practice": ["В какие моменты вы ощущаете себя наиболее «живым» и настоящим — что вы тогда делаете и с кем?", "Как вы реагируете на критику своего поведения — принимаете её на свой счёт или ощущаете, что она вас не касается?"]}, "10-34": {"name": "Канал Исследования", "design": "Дизайн Следования собственным убеждениям", "type": "Генерируемый", "page": 194, "classic": "Канал Исследования принадлежит малому Контуру Центрирования Индивидуальной группы и выполняет в нём творческую роль. Он соединяет Сакральный центр с G-центром: 34-е ворота Силы дают стойкость отстаивать свои убеждения, а 10-е ворота Поведения «Я» запускают поведение, ведущее к уважению и любви к себе. Подзаголовок книги — «Дизайн Следования собственным убеждениям». Как творческий канал Центрирования, он влияет на всю структуру контуров в дизайне, но эта энергия обращена не на окружающих: она сосредоточена на том, чтобы человек оставался центрированным в своём. Канал генерируемый, поэтому чистая сила 34-х ворот взаимодействует с другими корректно только через Сакральный отклик. Итог — личное мастерство поведения, которое укрепляет любовь к себе даже у тех, кто привык ставить служение общине выше.", "inner": "Человек здесь, чтобы следовать своим убеждениям, какими бы необычными они ни были, и вести себя независимо; когда этим руководит Сакральный отклик в нужный момент, это даёт удовлетворение без чувства вины. Своей жизнью он показывает, чем хорошо поведение, идущее из отклика, и сам глубже соприкасается с любовью к себе. Генераторская аура с этим каналом притягивает много внимания, и будет ли оно доброжелательным, зависит от терпения оставаться в отклике. Некорректность видна быстро: ложное «я» канала звучит косно и эгоцентрично — «буду таким, нравится вам или нет; только не стойте у меня на пути». Книга связывает расцвет канала с самоуважением, а не с противопоставлением себя другим.", "together": "Контур Центрирования усиливает у окружающих независимость и уверенность, основанные на любви к себе; книга называет это миром, о котором мечтают Индивидуалы, — где каждый живёт свою уникальность без «палок в колёсах». Как электромагнит между двумя людьми канал делает отношения неповторимыми и способен ломать старые шаблоны. Если же так соединились люди с сильными коллективными или племенными привязанностями, не понимающие силы отклика, могут возникать неожиданные противоречия.", "plain": "Вам важно жить по своим убеждениям и поступать по-своему, даже если это непривычно для других. Это приносит радость, когда идёт от внутреннего «да», а не из упрямства. Чем больше вы уважаете себя, тем легче другим рядом с вами тоже быть собой.", "practice": ["Вспомните случай, когда вы поступили по-своему вопреки ожиданиям: было ли это внутреннее «да» или желание доказать свою правоту?", "Как люди обычно реагируют на вашу независимость — и от чего, по вашим наблюдениям, это зависит?"]}, "10-57": {"name": "Канал Совершенной формы", "design": "Дизайн Выживания", "type": "Проецируемый", "page": 166, "classic": "Селезёнка, центр телесной осознанности и выживания, соединяется здесь с G-центром идентичности: 57-е ворота Интуитивной ясности подсказывают, 10-е ворота Поведения «Я» воплощают подсказку в поведении. Канал Совершенной формы — творческий канал Интеграции, той особой системы вне трёх больших групп, которую книга называет основой индивидуализации и защиты формы. Сама книга определяет его как искусство выживания: поведение, выросшее из интуиции, самоуважения и любви к себе, — краеугольный камень способности человека выживать в одиночку. 57-е ворота дают тонкий слух к характеру звуков: когда тон голоса значит больше, чем слова, включается древняя, спонтанная мудрость, лежащая за пределами мыслей и эмоций. Канал проецируемый; его влияние раскрывается через то, как человек живёт, а не через усилие быть замеченным. Подзаголовок — «Дизайн Выживания».", "inner": "Когда интуитивные импульсы направляют поведение от момента к моменту, человек освобождается от беспочвенных страхов будущего, мешающих любить себя и мир. Его дар — лёгкость существования и умение «соображать на ходу», которое шлифует форму и обеспечивает выживание прямо сейчас; в этом книга видит красоту, приносящую радость. Такое творчество спонтанно и непохоже ни на неторопливую саморефлексию ума, ни на эмоциональную глубину, которая раскрывается со временем. Ловушка — позволить страхам будущего и голове перехватить управление у интуиции. Проживая себя по-настоящему, человек строит здоровую и красивую жизнь, и эта уникальность сама приглашает других ценить жизнь собой.", "together": "Эти люди создают то, что любят, и любят то, что создают; признание не служит им мотивом. Заметно, но ненавязчиво они делают пространство вокруг здоровее и красивее. Книга отмечает, что многие архитекторы, дизайнеры, художники и врачи с этим каналом формируют характер окружающего мира, даже не задумываясь об этом.", "plain": "Вы хорошо чувствуете, как поступить в моменте, — часто раньше, чем успеваете это обдумать. Когда вы доверяете этому чутью, жизнь становится легче, а тревоги о будущем отступают. Вам свойственно делать красивым и удобным всё, к чему вы прикасаетесь, — просто потому, что вам это нравится.", "practice": ["Замечали ли вы, что интонация человека говорит вам больше, чем его слова? В каких ситуациях это помогало?", "Что происходит, когда вы отменяете мгновенное внутреннее решение ради «разумного» плана?"]}, "11-56": {"name": "Канал Любознательности", "design": "Дизайн Искателя", "type": "Проецируемый", "page": 230, "classic": "Аджна, центр осмысления, через Канал Любознательности выходит к Горлу: 11-е ворота Идей наполняют его образами и мыслями, 56-е ворота Стимуляции превращают их в рассказ. Это абстрактное крыло Коллективной группы, Контур Ощущений: он обращён к прошлому опыту и делится им, а социальное обязательство Коллектива — именно делиться. В отличие от логики с её точными фактами, абстрактный голос собирает обрывки сведений и соединяет их, заполняя пробелы воображением, — так знание входит в жизнь в виде историй. Подзаголовок книги — «Дизайн Искателя»: поиск здесь важнее находки, а его формула звучит примерно так: «Смотрите, что я обнаружил: это то, во что я верил, и оно оказалось истиной». Канал проецируемый и не связан с мотором; его дар раскрывается, когда у рассказчика есть слушатели. Из таких людей выходят рассказчики, учителя и искатели истины, обучающие на собственном опыте.", "inner": "Подача у такого человека может быть завораживающей: он нанизывает идеи и философские размышления о том, что значит быть опытным человеком, и украшает ими рассказ, который учит или развлекает. Истории бывают слегка преувеличены или содержат полуправду — как рассказ ребёнка о дне в школе, — но всё равно цепляют. Сила веры превращает убеждение в правду: факты интересуют его меньше, чем наглядность и поучительность, поэтому рассказы похожи на притчи. Важная деталь, которую подчёркивает книга: эти истории рождены личным опытом, но как руководство для самого рассказчика бесполезны — они адресованы другим, нынешним и будущим поколениям, для размышления. Ловушка — делиться ими невпопад, когда аудитория не готова.", "together": "Люди по-прежнему восхищаются теми, кто умеет рассказать хорошую историю и дать живой комментарий к происходящему. Насколько аудитория откроется магии рассказа, зависит от своевременности. Следуя Стратегии и Авторитету, носители канала делятся с удовольствием и вдохновляют, развлекают и будят интерес у остальных.", "plain": "Вам интересно всё новое, и вы умеете рассказывать так, что заслушаешься. Ваши истории больше про смысл, чем про точные факты, и они особенно ценны для других. Рассказывайте, когда вас готовы слушать, — тогда это радует и вас, и слушателей.", "practice": ["Какую историю из своей жизни вы рассказываете чаще всего — и что, по-вашему, слушатели из неё выносят?", "Чем для вас обычно ценнее поиск — тем, что вы находите, или самим процессом и впечатлениями?"]}, "12-22": {"name": "Канал Открытости", "design": "Дизайн Социальности", "type": "Манифестируемый", "page": 190, "classic": "Солнечное Сплетение с его эмоциональной волной выходит здесь прямо к Горлу: 22-е ворота Открытости дают социальную теплоту, 12-е ворота Осторожности сдерживают её и направляют к тем, кто готов к переменам. Канал Открытости — социальный канал Контура Знания в Индивидуальной группе, и управляет им не дружелюбие само по себе, а положение волны: «когда я в настроении». Книга связывает 12-е ворота с мутацией гортани, которая дала людям артикуляцию и способность трогать других самим качеством голоса. Индивидуалы мало заняты племенными связями или коллективным «делением» — они создают восприимчивую атмосферу, чтобы принести остальным новое, преображающее понимание. Канал манифестируемый: мотор напрямую связан с Горлом, и человек может сам говорить и действовать. Ключ при этом — дождаться, пока желание общаться действительно появится.", "inner": "Острое чувство момента и готовности слушателей подсказывает, когда включить теплоту и социальные навыки, чтобы словом стать катализатором перемен в чужой жизни. Главный инструмент — голос и интонация: ими этот человек трогает, учит и меняет людей. Когда настроение и тайминг совпадают, через выступления, поступки, стихи или музыку он даёт другим прожить весь диапазон чувств. Авторитет здесь — Солнечное Сплетение, поэтому импульсивные действия не работают; сила влияния растёт из терпения и глубины чувств, которые он позволяет себе прожить. Ловушка — оказаться втянутым в общение на спаде волны: тогда появляются резкость и раздражение, а череда таких неудач толкает к замкнутости и изоляции.", "together": "Индивидуалы заметнее других и потому живут со страхом, что их непохожесть сочтут неуместной. 22-е ворота слушают левым ухом и слышат то, что хотят услышать, — им нужно услышать несколько раз, но в хорошем настроении они улавливают подлинный смысл сказанного. Когда контакты подчиняются настроению, барьеры рушатся, и индивидуальное отличие обретает настоящую силу.", "plain": "Ваше желание общаться приходит и уходит вместе с настроением, и это нормально. Когда вы в духе, ваш голос и слова трогают людей и могут многое изменить. Если настроения нет, лучше не заставлять себя быть на виду — так меньше шансов наговорить лишнего.", "practice": ["Как отличается ваше общение в дни, когда вам хочется говорить, от дней, когда вы общаетесь «по обязанности»?", "Замечали ли вы, что люди реагируют больше на ваш тон голоса, чем на сами слова?"]}, "13-33": {"name": "Канал Блудного сына", "design": "Дизайн Свидетеля", "type": "Проецируемый", "page": 222, "classic": "Канал Блудного сына целиком соткан из отражений и воспоминаний. Он соединяет G-центр с Горлом: 13-е ворота Слушателя хранят тайны и собирают воспоминания, 33-и ворота Уединения уходят в тишину, чтобы обдумать опыт и дождаться, когда всплывёт глубокая истина. Это часть абстрактного Контура Ощущений Коллективной группы: здесь завершается цикл эмпирического созревания, и прожитое становится уроком для других. Голос канала: «Я помню свой опыт (или свою неопытность)». Книга видит в этом эволюционное преимущество вида — преемственность цивилизации и устойчивость от поколения к поколению. Канал проецируемый, поэтому накопленное лучше всего передаётся, когда его готовы принять. Подзаголовок — «Дизайн Свидетеля».", "inner": "Это одарённый слушатель и «архивариус», который собирает истории, секреты и памятные вещи, а потом уединяется, чтобы всё упорядочить и подготовить уроки. Испытание здесь — время: тайны раскрываются только в нужный момент, а некоторые не раскрываются никогда. Человеку свойственно желание порвать с семейными и общественными шаблонами и выбирать лишь тот опыт, из которого хочется чему-то научиться. Ловушка — входить в опыт с надеждами, терять терпение и упускать ценность завершённого цикла. Высший урок, по книге, — спокойная сдача своему процессу в роли наблюдающего «пассажира»: тогда терпеливое осмысление со временем открывает большие истины.", "together": "Такие люди склонны к фотографии, мемуарам, собиранию чужих воспоминаний; среди них бывают политики, комики, доверенные лица. Им легко доверяют секреты. Будучи обращены к прошлому, они слабы в предсказаниях для решения сегодняшних задач, но первыми скажут, что жизнь в итоге имеет смысл.", "plain": "Вы хорошо слушаете и многое запоминаете, а потом вам нужно время побыть одному, чтобы всё переварить. Из пережитого у вас рождаются выводы, которые полезны и вам, и другим. Делиться ими лучше тогда, когда сами чувствуете, что время пришло.", "practice": ["Сколько времени вам обычно нужно после яркого события, чтобы понять, чему оно вас научило?", "Что вы чувствуете, когда опыт не оправдывает ваших надежд, — разочарование или интерес к тому, что из него можно вынести?"]}, "16-48": {"name": "Канал Волны проявления", "design": "Дизайн Таланта", "type": "Проецируемый", "page": 210, "classic": "Как навык становится талантом — главный вопрос Канала Волны проявления. Он ведёт от Селезёнки к Горлу: 48-е ворота Глубины несут внутреннее знание, которое нельзя постичь умом, — оно доступно, когда человек доверяется инстинктам тела, а 16-е ворота Навыков ищут новые способы экспериментировать и оттачивать мастерство. Это творческий канал логического Контура Понимания в Коллективной группе: вместе с каналом 58-18 он применяет глубину и навыки, чтобы решить задачу или отшлифовать то, что требует улучшения. Навыком может быть что угодно — от игры на инструменте до поиска математической формулы. Канал проецируемый, поэтому талант особенно расцветает при признании, приглашении и поддержке. Подзаголовок книги — «Дизайн Таланта».", "inner": "Человек создан соединять интуитивную глубину с многократной практикой своих навыков. Ключ к таланту — полностью отождествиться с тем, что любишь делать, потому что мастерство требует большой вовлечённости и бесконечного повторения. Когда энтузиазм сочетается с долгой шлифовкой, мастерство начинает менять сам паттерн и позволяет выразить свою уникальную «волну». Книга даёт ориентир: чтобы выйти за пределы техники, телу нужно около семи лет, а чтобы наполнить это глубиной, может понадобиться вся жизнь. Ловушка — бросить практику до того, как навык успел превратиться в талант.", "together": "Носителям канала важно, чтобы их талант признавали и приглашали, а в ответ давали ресурсы для дальнейшей практики; деньги книга называет одной из форм признания. Канал описывает и отношения мастера и ученика: мастер растёт, передавая технику, ведь талант — это «1 процент дара и 99 процентов настойчивых тренировок». Каждый новый мастер добавляет к общему паттерну свою перспективу.", "plain": "У вас есть способность довести любимое дело до настоящего мастерства, но это требует много лет упорной практики. Чем больше вы любите то, чем занимаетесь, тем легче вам повторять и совершенствоваться. Вашему таланту помогает, когда его замечают и поддерживают — в том числе материально.", "practice": ["Каким делом вы готовы заниматься снова и снова, не уставая от повторения?", "Как на вашу мотивацию практиковаться влияют признание и поддержка со стороны других людей?"]}, "17-62": {"name": "Канал Принятия", "design": "Дизайн Организатора", "type": "Проецируемый", "page": 214, "classic": "Канал Принятия описывает ум, который всё время раскладывает мир по полочкам. Он соединяет Аджну с Горлом: 17-е ворота Мнений — ворота правого глаза — видят паттерн как картинку, а 62-е ворота Деталей переводят её в слова. Книга отводит 62-м воротам особую роль — создание языка, которым мы называем, упорядочиваем, оцениваем и придаём смысл увиденному. Это часть логического Контура Понимания в Коллективной группе: логика придаёт форму общему мышлению ради взаимопонимания и смотрит в будущее, проверяя паттерны на жизнеспособность. Канал проецируемый и не связан с мотором, поэтому его мнения лучше принимаются, когда их просят. Подзаголовок — «Дизайн Организатора»; книга отмечает также, что через 62-е ворота люди находят общий язык с млекопитающими, что способствует дрессировке.", "inner": "Ум постоянно сортирует детали по своей «ментальной файловой системе» и подгоняет новое под собственную «картину мира». Фраза «я вас не понимаю» означает здесь лишь одно: «у меня не получилось встроить ваш взгляд в мою картину». Из-за давления на Горло человек ощущает облегчение, когда делится подробными мнениями или объясняет, что понимает, а что нет, — но важно учитывать момент и готовность слушателей. Дар — логично организовывать дела для других: проекты, события, пространство, — при этом собственный рабочий стол может его совсем не волновать. Ловушка — высказываться без приглашения и утомлять окружающих банальностями.", "together": "У таких людей врождённый талант объяснять: они переводят визуальные паттерны — формулы, теории, гипотезы — в язык, чтобы их можно было проверить. Ожидание приглашения говорить даёт своевременность, ясность и меньше сопротивления. Логике нужны споры как форма проверки, но на личном уровне они остаются источником стресса.", "plain": "Вы умеете навести порядок в информации и ясно объяснить, как всё устроено. Если что-то не укладывается в вашу картину мира, вы просто этого пока не понимаете — и это не значит, что оно неверно. Ваши мнения лучше всего слышат, когда вас о них спрашивают.", "practice": ["Когда вы говорите «я этого не понимаю», что за этим чаще стоит — несогласие или то, что новое пока не встроилось в вашу картину?", "Как меняется реакция людей на ваше мнение, когда вас о нём спросили, и когда вы высказали его сами?"]}, "18-58": {"name": "Канал Суждений", "design": "Дизайн Ненасытности", "type": "Проецируемый", "page": 208, "classic": "От Корневого центра к Селезёнке идёт Канал Суждений: 58-е ворота Жизненности заряжают радостью и любовью к жизни, 18-е ворота Исправления замечают то, что нездорово, вышло из равновесия или требует починки. Ненасытность канала, по книге, — следствие именно радости: 58-е говорят «больше и лучше», а 18-е направляют этот импульс. Это логический Контур Понимания Коллективной группы, и суждение здесь опирается на проверку паттернов — сравнение того, что работает, с тем, что не работает. Книга называет канал «надсмотрщиком» и связывает с искусством мастерства, а его высшую цель — вернуть радость, утраченную в однородной массе обусловленного общества. Канал проецируемый, поэтому критика полезна, когда её ждут. Подзаголовок — «Дизайн Ненасытности».", "inner": "Совершенство недостижимо даже для убеждённого перфекциониста, потому что паттерны всё время меняются. Желание судить и исправлять включается, когда человек чем-то недоволен или чувствует потребность бросить вызов. Главная ловушка — перенести это на себя и близких: тогда начинается бесконечный поиск ошибок и недовольство собой, родителями, учителями, властью, а непрошеная критика превращается в брюзжание, которое никто не хочет слушать. В Дизайне Человека корректным считается делиться суждением по приглашению — тогда оно приносит настоящую радость, а спрашивающие готовы его принять. Такой подход позволяет беречь заряд для того, что действительно важно.", "together": "Книга советует ждать, пока попросят поделиться решениями: тогда вызов адресован тому, к чему окружение открыто. Её пример — тюбик зубной пасты: логика требует сжимать снизу, Индивидуал жмёт где удобно, а безличное коллективное решение — устройство, выдавливающее пасту равномерно. Взаимно согласованные решения сохраняют отношения и делают сам процесс лучше.", "plain": "Вы сразу видите, что можно сделать лучше, и вам хочется это исправить. Когда вас просят высказаться, ваши замечания очень ценны, а непрошеная критика часто вызывает раздражение. Полезно не направлять этот взгляд на себя и близких слишком строго.", "practice": ["Как часто ваши замечания бывают о себе или близких людях, а как часто — о деле или общей задаче?", "Вспомните случай, когда вас попросили оценить что-то: как приняли ваше мнение по сравнению с непрошеным советом?"]}, "19-49": {"name": "Канал Синтеза", "design": "Дизайн Чувствительности", "type": "Проецируемый", "page": 246, "classic": "Канал Синтеза соединяет Корневой центр с Солнечным Сплетением, связывая давление базовых потребностей с эмоциональной волной. 19-е ворота Потребности побуждают сближаться и проявлять взаимозависимость, 49-е ворота Принципов отвергают то, что несовместимо с высшими идеалами, и держат связь людей друг с другом и с духом. Это Племенной Контур Эго, где тема — поддержка и сделка; книга напоминает, что сделка здесь исторически скреплялась прикосновением, например рукопожатием. Эмоциональная частота принятия или отвержения — «клей», определяющий, кто свой, кто заслуживает поддержки и место за столом; логики или абстрактного опыта в ней нет. Код Племени звучит как «люби, уважай и слушайся», а лояльность, ключ к выживанию, управляется эмоциональной волной. Канал проецируемый; подзаголовок — «Дизайн Чувствительности».", "inner": "Такой человек очень чувствителен к своему месту в жизни: ему важно быть нужным и поддерживающим и/или желанным и поддержанным. Его поле — семья, как бы она ни понималась, и ради её благополучия он готов работать над собой. Книга приводит пример: прежде чем переходить к совместной жизни, стоит дать себе время — через долгие ухаживания узнать глубину своей волны и то, как она отзывается в партнёре. Внутри своего «племени» для него важны три вещи: защита ресурсов, неприкосновенность территории и ясная система веры; потенциальный дар — видеть баланс между практичностью и справедливостью. В ложном «я» канал проявляется постоянным и неуместным отвержением себя и других.", "together": "Канал закладывает принципы брачных отношений — архетип жениха и невесты, частоту, сплачивающую семью, источник племенных традиций, ритуалов и праздников. Давление 19-х ворот толкает соединяться с людьми так, чтобы это приносило радость. Книга связывает его и с межвидовой связью человека с животными — приручением и дрессировкой.", "plain": "Вам важно чувствовать, что вы нужны близким и что они рядом. Вы тонко ощущаете, кто вам «свой», и долго решаете, кого впустить в близкий круг. Решения о серьёзных отношениях лучше принимать не спеша, когда эмоции улягутся.", "practice": ["Что для вас важнее в отношениях сейчас — быть нужным другим или чувствовать поддержку от них?", "Как вы обычно понимаете, что человек стал для вас «своим», и сколько времени на это уходит?"]}, "20-34": {"name": "Канал Харизмы", "design": "Дизайн, где осознанность должна стать действием", "type": "Манифестируемый / генерируемый", "page": 164, "classic": "Канал Харизмы проводит грубую физическую мощь 34-х ворот Силы из Сакрала прямо к 20-м воротам Настоящего в Горле. Книга называет его каналом чистого Манифестирующего Генератора: генерируемая энергия так быстро превращается в действие, что почти обгоняет отклик, — отсюда трудность усидеть на месте. Он входит в Канал Интеграции, тему самоусиления: человек поглощён тем, чтобы поддерживать и проявлять собственную жизненную силу, и именно этим, по логике системы, вносит вклад в выживание всех. Канал лежит на одной из трёх оппозиций Рейв Мандалы (две другие — 43-23 и 37-40), поэтому встречается часто и служит устойчивой жизненной силой в мире. Образ книги — воин, который должен сдаться будде: манифестирующий порыв ждёт отклика на внешний стимул, чтобы харизма шла в мир корректно. Без этой осознанности та же мощь легко становится одержимостью или хаотичными спонтанными рывками.", "inner": "Дар канала — огромная работоспособность и способность долго держать дело, если оно по-настоящему любимо. Книга описывает корректное состояние как полную поглощённость приносящим удовлетворение занятием, при которой человек недоступен для окружающих, — и именно это естественно вдохновляет других; так и рождается харизма. Главная ловушка — когда сакральный отклик подменяют умственные «я должен» и «мне следует»: сила рассеивается, отнимает здоровье и перестаёт быть примером. Корректным книга называет действие из отклика, то есть Стратегию и Авторитет, а не из идеи о том, чем стоит заняться.", "together": "Со стороны такие люди выглядят вечно занятыми и недоступными; другие могут завидовать их энергии, но подключиться к ней не могут. Их дилемма — чрезмерная занятость и неумение заметить, где нужна направляющая рука. Если в собственном дизайне нет авторитетного руководства (книга приводит в пример интуицию 57-х ворот или поведение 10-х), здорово прислушиваться к совету людей с индивидуальным знанием и ясностью канала 43-23.", "plain": "У вас может быть очень много энергии, которая сразу хочет стать делом. Лучше всего она работает, когда вы откликаетесь на то, что действительно увлекает, а не делаете то, что «надо». Тогда ваша погружённость сама по себе притягивает и заряжает других.", "practice": ["В какие моменты моя занятость наполняет меня, а в какие — превращается в бег по кругу?", "Как часто я начинаю действовать раньше, чем почувствовал внутреннее «да», и чем это обычно заканчивается?"]}, "20-57": {"name": "Канал Нейронной волны", "design": "Дизайн Проникающей осознанности", "type": "Проецируемый", "page": 186, "classic": "Здесь интуиция Селезёнки — 57-е ворота Интуитивной ясности — без посредников, «волной знания», выходит к 20-м воротам Настоящего в Горле. Это канал Нейронной волны, дизайн Проникающей осознанности: индивидуальное озарение, рождённое древними инстинктами и привязанное к мгновению. Его голос книга формулирует как «Я знаю, что я сейчас живой». В Контуре Знания, чья тема — усиление, такой канал важен тем, что пробуждает в других их собственный внутренний «разум выживания». Он проецируемый: Селезёнка не мотор, поэтому интуиция может ясно осознать и высказать, что ведёт к благополучию, но действие за этим не обязательно последует. Его влиянию нужен правильный момент и признание.", "inner": "Острая чувствительность к звукам и вибрациям позволяет схватывать суть раньше других и «думать на ходу». Человек, укоренённый в настоящем, не боится завтрашнего дня: он просто знает, что делать, и тело движется вместе с этим знанием. Ловушка — проигнорированный импульс: осознанность момента не срабатывает, и можно пострадать. Тот же фокус на настоящем мешает слышать чужие «знания» — ему не нравится, когда говорят, что делать. Книга связывает корректное использование дара со Стратегией и Авторитетом: тогда его слова снимают недопонимание, а не вызывают сопротивление.", "together": "Книга описывает взаимовыгодную связь 57-х ворот с 28-ми, которые борются с вопросами о смысле и ценности жизни: 28-е могут вытащить 57-е из сосредоточенности на себе, а поиск смысла подталкивает 57-е открыть своё интуитивное знание для чужих вопросов. При верном тайминге люди с этим каналом становятся искрой мутационных перемен для окружающих.", "plain": "Вы можете мгновенно чувствовать, что происходит, и тут же это формулировать — без долгих размышлений. Это знание о том, что полезно здесь и сейчас, но оно не всегда подталкивает к действию. Ваши слова сильнее всего, когда их готовы услышать.", "practice": ["Вспомните случай, когда я отмахнулся от мгновенного внутреннего сигнала. Что было потом?", "Как я реагирую, когда мне советуют, как поступить, а у меня уже есть своё ощущение момента?"]}, "21-45": {"name": "Канал Денег", "design": "Дизайн Материалиста", "type": "Манифестируемый", "page": 250, "classic": "Канал Денег связывает 21-е ворота Охотника в Сердечном центре с 45-ми воротами Собирателя в Горле. Книга даёт ему имя «Дизайн Материалиста» и называет самым целеустремлённым из манифестирующих: его голос — «Это я решаю, вставать во главе, контролировать или нет». Канал принадлежит Контуру Эго Племенной группы, где всё строится на поддержке и сделке, а 45-е ворота — единственный голос Племени, голос власти с последним словом: «Я имею / не имею». Он манифестируемый: воля Сердца выходит прямо в выражение, поэтому человек способен сам заявлять и запускать задуманное. Лучшее племенное лидерство в книге — сплачивать, защищать и обучать людей, пока все обеспечены и «в королевстве воцаряется мир». Внутри канала есть напряжение: 45-е защищают, но хотят решающего слова, 21-е служат, но стремятся к контролю, чтобы обеспечить отдых себе и другим.", "inner": "Задача — освоить материальный мир, стать в нём мастером и зарабатывать силой воли, защищая свои интересы и одновременно служа другим. Главная жизненная тема — контролировать и не быть под контролем; секрет успеха книга видит в определённой независимости. Человек готов много работать, но лучше всего, когда сам себе хозяин и сам выбирает ритм; даже без полного контроля ему нужно его ощущение. Ловушка — неумение доверять и делегировать: книга связывает это с лишней нагрузкой на сердце, а потребность в балансе работы и отдыха считает частью природы канала.", "together": "Материалисту для настоящего успеха нужна поддержка и сотрудничество Племени — от торговли между деревнями до корпораций. По книге, канал особенно хорошо работает как электромагнит между двумя людьми: 45-е — владелец или «король», который передаёт полномочия, 21-е — «президент» или премьер-министр с сильным эго, обязанный принести выгоду себе, владельцу и всем участникам.", "plain": "Вам важно самим управлять своими делами и деньгами и решать, что и когда делать. Вы можете быть сильным хозяином, который заботится о своих людях. Трудная часть — довериться другим и разделить с ними нагрузку.", "practice": ["В каких делах мне нужно ощущение контроля, а где я могу спокойно его отпустить?", "Что мне мешает передать часть работы другим и как это сказывается на моих силах?"]}, "23-43": {"name": "Канал Структурирования", "design": "Дизайн Индивидуальности (от гения до фрика)", "type": "Проецируемый", "page": 182, "classic": "От 43-х ворот Озарения в Аджне к 23-м воротам Ассимиляции в Горле идёт канал Структурирования. Знание, вызревшее во вдохновении канала 61-24, здесь прорывается внезапными озарениями, а 23-и ворота пытаются их усвоить и облечь в слова. Книга называет его дизайном Индивидуальности — «от гения до фрика»: в Контуре Знания он запускает мутационный процесс, меняющий сам способ видеть и думать, например через ключевые слова как сверхэффективную форму высказывания. Канал проецируемый, и это решающе: даже блестяще выраженное знание, высказанное не вовремя, вряд ли поймут и оценят. Поэтому его сила зависит от приглашения и признания, то есть от Стратегии и Авторитета.", "inner": "Вызов — отпустить контроль и позволить уму обрабатывать знание в своём темпе; заранее планировать слова не нужно и невозможно. Такой ум не только принимает знание, но и исследует неизвестное, всегда на шаг впереди. Когда человек делится озарением после приглашения, его не считают безумцем, и его идеи могут изменить Коллектив и Племя; когда говорит не вовремя — встречает отчуждение и может сам перестать доверять своему знанию. Книга предупреждает, что объяснять придётся много раз, прежде чем новая концепция утвердится.", "together": "Дар канала — находить более простые и быстрые способы что-то делать, и для организаций это может стать квантовым скачком. Оставаясь верными своему знанию, такие люди порой кажутся глухими к другим. Книга приводит слова Ра Уру Ху: индивидуальный ум всегда чувствует себя аутсайдером, который стоит на пороге и ждёт приглашения поделиться своим.", "plain": "Вам могут вдруг приходить идеи, как сделать что-то совсем по-новому. Чтобы их приняли, важно подождать, пока вас спросят, и учиться объяснять понятно. Иногда объяснять приходится не один раз — это нормально.", "practice": ["Как меняется отклик людей, когда я делюсь идеей по их просьбе, и когда — без неё?", "Замечаю ли я, что перестаю ценить собственные мысли после того, как их не поняли?"]}, "24-61": {"name": "Канал Осознанности", "design": "Дизайн Мыслителя", "type": "Проецируемый", "page": 180, "classic": "Канал Осознанности, дизайн Мыслителя, соединяет Теменной центр и Аджну: 61-е ворота Тайн несут давление познать непознаваемое, а 24-е ворота Рационализации превращают его в концепцию. Это индивидуальное мышление Контура Знания, и книга отделяет его от двух коллективных собратьев: оно не осмысляет прошлое, как абстракция (64-47), и не предсказывает будущее по паттернам, как логика (63-4). Здесь работает «акустический» ум, который перемалывает одно и то же, пока в паузе не родится новая мысль — сатори, внезапное «я знаю». Канал проецируемый: вдохновение уже присутствует в уме и ждёт, пока жизнь пригласит направить его на что-то. Его задача — понять, что действительно познаваемо и важно, и признать, что всего знать невозможно.", "inner": "Такой ум способен воодушевлять других совершенно новым взглядом на жизнь и ломать старые логические и абстрактные модели. Ловушка — пытаться управлять мышлением и использовать его для достижения целей: по книге, знание либо случается, либо нет. Корректно — отдаться внутренней правде и дать ей оформиться через 24-е ворота в своё время, пока ум полон «белого шума» вдохновения. Ум близок к тайне и всё время занят, поэтому человек любит тишину; книга упоминает музыку и игру на инструменте как отдых от давления думать.", "together": "Новая мысль приходит как незваная гостья, когда человек поглощён настоящим, и ему не нужно специально что-то «делать», чтобы её вызвать. Главные трудности в общении — ухватить неявные, но сильные истины и убедить других в их ценности. Ключ к успеху книга видит в умении отличать то, что нужно знать, от того, что не нужно.", "plain": "Ваша голова может долго крутить одну мысль, а потом вдруг выдать ясный ответ. Торопить это бесполезно — озарение приходит само. Тишина и музыка помогают вам отдохнуть от постоянного думания.", "practice": ["Какие вопросы я гоняю по кругу, хотя ответ на них, возможно, мне и не нужен?", "Что обычно происходит перед тем, как ко мне приходит внезапная ясность?"]}, "25-51": {"name": "Канал Инициации", "design": "Дизайн Потребности быть первым", "type": "Проецируемый", "page": 196, "classic": "Состязательная энергия 51-х ворот Шока из Сердечного центра соединяется здесь с 25-ми воротами Духа «Я» в G-центре — способностью Высшего «Я» любить живое и неживое в равной мере. Так рождается канал Инициации, дизайн Потребности быть первым. Он входит в малый Контур Центрирования и, по книге, единственный канал Эго вне Племенного контура, связывающий племенную и индивидуальную темы. Суть канала — увидеть в другом потенциал индивидуализации и, если есть приглашение, дать шокирующий толчок, который запускает движение к этому потенциалу. Тип проецируемый: инициацию нельзя навязать, её нужно дождаться. Сюда же книга относит естественную состязательность — вызов человечеству идти вперёд, быть первым и побеждать.", "inner": "Соперничество при корректном входе выводит человека за его творческие и физические пределы; каждый прорыв даёт новое ощущение глубины своего духа, а каждый триумф становится для других примером храбрости. Но инициация в книге — мистический процесс, которым нельзя управлять: кто её ищет, не находит, она должна найти человека сама. Ловушка — активно выискивать, кого бы встряхнуть: это грозит отвержением, обидой и ощущением нереализованности. Стратегия и Авторитет названы здесь самыми сильными мистическими инструментами; книга советует следовать велению сердца, чтобы пережить встреченный шок.", "together": "Инициация сдвигает человека от «мы» к «я». Книга сравнивает носителей канала с шаманами, которые с невинностью прыгают в неизвестность и затем помогают другим перейти на более глубокие уровни сознания; шок приземления неизбежен. Иногда инициирующим «приглашением» становится сама жизнь — например, неожиданное потрясение, которое меняет направление.", "plain": "В вас может быть сильный дух соревнования и желание быть первым. Вы способны встряхнуть другого человека так, что он сделает шаг к себе, но лучше, когда об этом просят. Самые важные повороты в вашей жизни, скорее всего, приходят сами, а не по плану.", "practice": ["Когда моё желание быть первым вдохновляет других, а когда отталкивает?", "Бывало ли, что я пытался «разбудить» человека без его просьбы? Как он это принял?"]}, "26-44": {"name": "Канал Сдачи", "design": "Дизайн Передающего", "type": "Проецируемый", "page": 244, "classic": "Канал Сдачи — единственная прямая связь Селезёнки с Сердцем: 44-е ворота Бдительности несут племенную память и инстинкт, 26-е ворота Эгоиста добавляют силу воли. Книга называет его дизайном Передающего и «капиталистом», занятым искусством предпринимательства. Это творческий канал Контура Эго, а значит, его поле — Племя, поддержка и сделка. По сути здесь работает интуитивная бдительность: замечать всё, что угрожает жизнеспособности Племени, и улучшать или заменять это, причём «нюхом» угадывать, что людям нужно, раньше их самих. Канал проецируемый: лучше всего он работает, когда рынок или группа признаёт дар и сама просит что-то продвигать. Книга также связывает 26-е ворота с тимусом и считает канал одним из важных звеньев здоровья тела.", "inner": "Дар — интуитивно оценивать людей и подбирать им товары, занятия и даже идеи. Взамен человек ждёт справедливой платы и здорового баланса работы и отдыха: восьмичасовой офисный день не для него, зато за меньшее время он успевает больше многих. Инстинкту здесь стоит доверять: если человек или проект «плохо пахнет», лучше не входить. Ловушка — «продавать» без признания и поддержки; книга подчёркивает, что признание даёт платформу, с которой говорить убедительно.", "together": "Передающий чувствует, какой способ убеждения сработает, и на ходу подстраивается под меняющийся рынок, умея «массировать» чужое эго. Его сделка звучит как «продаю вещь за такую-то цену», а заработанное распределяется по команде, и отношение команды зависит от того, какие ресурсы он приносит. Книга перечисляет подходящие роли: режиссёр, коммерческий представитель, рекламщик, политик, дипломат.", "plain": "Вы хорошо чувствуете, что людям нужно, и умеете это им предложить. Вы работаете быстро, но вам важен отдых и честная оплата. Ваше чутьё на «не тех» людей и проекты стоит слушать.", "practice": ["Насколько я доверяю своему первому ощущению «не то» в отношении человека или проекта?", "Где моё умение убеждать служит людям, а где я сам замечаю, что давлю?"]}, "27-50": {"name": "Канал Сохранения", "design": "Дизайн Попечительства", "type": "Генерируемый", "page": 238, "classic": "Канал Сохранения, дизайн Попечительства, соединяет 27-е ворота Заботы в Сакрале с 50-ми воротами Ценностей в Селезёнке. Это один из двух каналов малого Контура Защиты, который книга сравнивает с колыбелью Бодиграфа. Если 59-6 отвечает за то, чтобы жизнь появилась, то здесь мгновенный Сакральный отклик реагирует на уязвимость созданного и пробуждает «холодную» селезёночную осознанность: о ком и о чём нужно позаботиться. Канал генерируемый: энергия заботы доступна через отклик и потому сама по себе не бесконечна. Он уравновешивает тёплую эмоциональную сторону Бодиграфа ответственностью за тех, кто не может позаботиться о себе. Книга называет такую поддержку необходимым условием того, чтобы Племя и его ценности продолжали жить.", "inner": "Аура такого человека сама вызывает доверие, и к нему тянутся за поддержкой — от отстаивания законов и ценностей «территории» до заботы о детях, больных и стариках. Он легко берёт ответственность, порой слишком много; узнать, какая ответственность корректна, по книге, можно только через Стратегию и Авторитет. Важная мысль канала — забота начинается с себя: только сильный и здоровый человек может вести других к здоровой жизни; книга называет это «просветлённым эгоизмом» и отличает от потакания себе. Тот, кто хочет помощи, должен попросить — тогда отклик покажет, есть ли на это энергия.", "together": "В канале два механизма защиты: 50-е ворота следят за преемственностью Племени и отстаивают его ценности и законы, а 27-е воспитывают, учат и исцеляют от обусловливания следующее поколение. Забота распространяется и на старших, чью мудрость нужно сохранить, и даже на общую инфраструктуру сообщества.", "plain": "Люди легко вам доверяют и часто приходят за помощью. Вы умеете заботиться, но сил хватает не на всех, поэтому важно сначала позаботиться о себе. Лучше помогать тогда, когда вас просят, и прислушиваться, откликается ли что-то внутри.", "practice": ["Какую ответственность я взял на себя, не почувствовав внутреннего отклика?", "Как изменяется моя забота о других, когда я сам отдохнувший и здоровый?"]}, "28-38": {"name": "Канал Борьбы", "design": "Дизайн Упорства", "type": "Проецируемый", "page": 184, "classic": "Адреналиновое давление 38-х ворот Борца из Корневого центра встречается здесь с 28-ми воротами Игрока в Селезёнке. Канал Борьбы, дизайн Упорства, несёт мысль, которую книга считает отличительной чертой человека: жизнь — больше, чем просто выживание. 28-е ворота различают, стоит ли борьба усилий, 38-е дают силу сохранять индивидуальную целостность и противостоять всему, что уводит от собственной истины. В Контуре Знания это мутационная сила, толкающая индивидуальность к высшему выражению её уникальности. Канал проецируемый: выбор битв не должен принадлежать уму. Смысл ищется и находится в самой борьбе, какой бы тяжёлой она ни была.", "inner": "Человек полон упорной решимости идти своим путём, даже если большинство против. Когда борьба корректна, нет ничего более удовлетворяющего, чем стоять на своём вопреки сильному противнику, и такие битвы вдохновляют других бороться за свой путь. Книга настаивает: входить в сражения нужно через Стратегию и Авторитет, а не по решению ума. Если борьба не оправдана или прожита некорректно, в теле копятся стресс и лишняя энергия; книга советует регулярную физическую нагрузку, которая сбрасывает давление и возвращает связь с интуицией.", "together": "Упорно слушая свою осознанность в моменте, люди с этим каналом приносят перемены в виде смены привычного направления. Они умеют убеждать, что эволюция — долгий процесс и за неё стоит бороться. Их упрямство окружающие могут воспринимать и как опору, и как вызов.", "plain": "Вам важно, чтобы в жизни был смысл, и ради него вы готовы бороться. Главное — выбирать сражения, которые действительно ваши. Физическая нагрузка помогает вам сбросить напряжение.", "practice": ["Какие мои нынешние «битвы» действительно мои, а какие я веду по привычке или из упрямства?", "Как физическая активность влияет на моё напряжение и ясность?"]}, "29-46": {"name": "Канал Открытий", "design": "Дизайн Преуспевающего там, где остальных ждет провал", "type": "Генерируемый", "page": 220, "classic": "Канал Открытий тянется от 29-х ворот Настойчивости в Сакрале к 46-м воротам Решительности «Я» в G-центре. В И-Цзин 29-я гексаграмма — «глубина в глубине», а 46-е ворота книга описывает как любовь к телу и пребыванию в нём, связывающую «транспортное средство» с направлением. Это абстрактный Контур Ощущений Коллективной группы, обращённый к прожитому опыту: его смысл открывается только в конце, когда опыт можно осмыслить и разделить. Канал генерируемый, и вся его выносливость держится на правильном «да» — сакральном отклике. Книга называет его дизайном Преуспевающего там, где остальных ждёт провал. Решительно и терпеливо пройденный до конца опыт, иногда длиной в годы, способен изменить то, как Коллектив воспринимает мир.", "inner": "Такой человек не меняет коней на переправе и не оглядывается, поэтому то, как он вошёл в опыт, определяет и удовлетворение, и уроки. Ему нужно уметь «потерять себя» в процессе и отпустить ожидания: пока опыт не прожит целиком, смысл может оставаться скрытым. Ловушка — обязательство, взятое умом: тогда, по книге, он рискует сам провалиться там, где другим сопутствовал бы успех, и получить фрустрацию вместо удовлетворения. Корректно — входить через Стратегию и Авторитет и доверять, что ты в нужном месте в нужное время.", "together": "Эти люди от природы доступны и склонны говорить «да» почти на любую просьбу, особенно если определённость бессознательная (красная). Учителем для них становится собственное прошлое, а не прогнозы: завершив и разобрав опыт, они понимают, что стоит повторить, и делятся этим с другими.", "plain": "Вы способны пройти долгий путь до конца там, где другие сдаются. Но для этого важно, чтобы ваше «да» было настоящим, а не из вежливости или расчёта. Смысл пройденного часто становится понятен только в самом конце.", "practice": ["На что я соглашался «головой» и как потом себя чувствовал в этом процессе?", "Какой прошлый опыт стал понятен мне только после того, как я прошёл его до конца?"]}, "30-41": {"name": "Канал Признания", "design": "Дизайн Сфокусированной энергии", "type": "Проецируемый", "page": 224, "classic": "41-е ворота Сжатия книга называет стартовым кодоном: с прохождением через них Солнца в январе начинается новый солнечный год, а в самих воротах заложены все возможности человеческого опыта. В канале Признания эти корневые фантазии о том, что «могло бы быть», доходят до 30-х ворот Чувств в Солнечном Сплетении и разогреваются до сильной потребности начать новое испытание. Это абстрактный Контур Ощущений: опыт ради свершения и завершения цикла, движимый надеждой, что действие победит тоску и скуку. Дизайн Сфокусированной энергии — проецируемый канал, сам по себе он не выходит в действие и опирается на эмоциональную волну. Голод, который он питает, утоляется лишь на время. По книге, эта культурная линия от неопытности к мудрости достигает вершины в канале 36-35.", "inner": "У человека сильное воображение и жажда глубоко прочувствовать жизнь; мечты и желания порождают ожидания или сомнения, ведь, по 30-м воротам, всё в руках судьбы. Со временем приходит понимание, что желание несёт и наслаждение, и боль, а удовлетворение недолговечно. Нетерпение нырнуть в новое уравновешивается терпением: Эмоциональному Авторитету нужно время, чтобы волна прошла и решение прояснилось. Корректным книга называет умение наслаждаться мечтой и каждым опытом самим по себе, не поддаваясь давлению ожиданий.", "together": "Давление двигаться может увлечь в «дикие скачки», в которые втянуты и другие люди, а после приключения у всех участников остаются глубокие воспоминания. Рассказ о прожитом в эмоциональных подробностях способен сильно вдохновлять слушателей.", "plain": "Вы много мечтаете и сильно хотите новых впечатлений. Важно не бросаться в новое сразу, а дать чувствам улечься и посмотреть, хочется ли этого по-прежнему. Тогда опыт приносит больше радости и меньше разочарования.", "practice": ["Как меняется моё желание чего-то нового, если я выжидаю несколько дней?", "Каких ожиданий я жду от мечты, и мешают ли они мне радоваться самому опыту?"]}, "32-54": {"name": "Канал Трансформации", "design": "Дизайн Движимого", "type": "Проецируемый", "page": 242, "classic": "Канал Трансформации, дизайн Движимого, связывает 54-е ворота Амбиций в Корневом центре с 32-ми воротами Непрерывности в Селезёнке. Он несёт энергию, с которой талантливый человек может собственными силами подняться из более низкого социального слоя. Это Контур Эго, Племя, и трансформация здесь понимается прежде всего в его контексте: 32-е ворота высматривают талант, движимые страхом, что Племя не выдержит очередного кризиса. Ощущение уязвимости превращается в амбицию — стремление подняться и измениться. Канал проецируемый: его движению вверх нужны признание и поддержка тех, кто выше. Книга упоминает и мистическую нить — 4-ю линию 54-х ворот, «Просветление/Затемнение», как топливо трансформации на высшем уровне.", "inner": "Трансформация здесь укоренена в преданности и самоотдаче: поддержка начинается с того, что таланты признают, а усилия поощряют те, кому человек помог осуществить их амбиции. Он охотно работает больше всех, доказывая свою ценность, и ловушка — трудоголизм. Ещё одно искажение, о котором говорит вводная, — страх неудачи, мутящий осознанность того, что вообще поддаётся изменению. Корректной целью книга называет испытать драйв признания, сохраняя здоровую независимость.", "together": "Чутьё Селезёнки подсказывает, какие ресурсы доступны для роста, а давление «заработать больше» постоянно двигает экономику. Устойчивая трансформация требует союзников и поддержки вышестоящих. Если человека с этим каналом распознали и поддержали, Племя вправе ждать ответной благодарности — так, по книге, выживает племенная система.", "plain": "Вам хочется расти и подниматься выше, и вы готовы для этого много работать. Ваш рост сильно зависит от того, замечают ли и поддерживают ли вас другие. Важно не загнать себя работой ради признания.", "practice": ["Где мои усилия признают, а где я продолжаю доказывать свою ценность без отклика?", "Как страх неудачи влияет на мои решения о новых шагах?"]}, "34-57": {"name": "Канал Силы", "design": "Дизайн Архетипа", "type": "Генерируемый", "page": 162, "classic": "Канал Силы книга называет Архетипом — образом того, что значит быть человеком как отдельным существом. Он соединяет 34-е ворота Силы в Сакрале с 57-ми воротами Интуитивной ясности в Селезёнке: огромная сакральная мощь подпитывает экзистенциальную осознанность, которая постоянно сканирует окружение на звуковом, вибрационном уровне. Канал входит в Интеграцию, тему самоусиления, и опирается на древнюю память млекопитающих — «Сражайся или убегай». Интуиция здесь — не рассуждение о том, что полезно, а мгновенный отклик на вибрации пространства и людей. Канал генерируемый: его сила включается через отклик и способна долго удерживать деятельность. По книге, именно через 57-е ворота начал расцветать весь процесс человеческой осознанности.", "inner": "Чтобы реагировать мгновенно (пример книги — отпрыгнуть от мчащейся машины), человеку нужно быть заземлённым и связанным с ощущением своего тела. Отсюда высокая избирательность к словам других: «правым ухом» он улавливает, что люди имеют в виду на самом деле. Следуя Стратегии, он высвобождает сплав интуиции и силы и учится полностью ему доверять; в расчёт здесь берутся прежде всего собственные потребности. Склонность к меланхолии книга советует просто принимать, не пытаясь исправить или объяснить.", "together": "Такие люди обычно не слишком любезны, когда кто-то вторгается в их уклад, и будут его отстаивать. Обретая свою силу, они становятся живым примером радости быть собой и откликаться на жизнь от момента к моменту.", "plain": "Вы можете мгновенно и точно реагировать на то, что происходит вокруг, — тело «знает» раньше головы. Вам важна независимость и свой ритм жизни. Грустные периоды не обязательно исправлять — их можно просто пережить.", "practice": ["Как я отличаю мгновенный телесный сигнал от тревожной мысли?", "Что я чувствую и как реагирую, когда кто-то вмешивается в мой привычный уклад?"]}, "35-36": {"name": "Канал Мимолетности", "design": "Дизайн «Мастера на все руки»", "type": "Манифестируемый", "page": 226, "classic": "Канал Мимолётности — эмоциональный манифестирующий путь из 36-х ворот Кризиса в Солнечном Сплетении к 35-м воротам Перемен в Горле. Книга характеризует его как канал, который не слушает предостережений логики и готов попробовать что угодно, лишь бы сдвинуть жизнь к новому опыту; его девиз — «Пришёл, увидел, победил… что дальше?». Это творческий канал абстрактного Контура Ощущений, коллективного и обращённого к опыту, который потом превращается в мудрость. 36-е ворота переживают свою неопытность как неадекватность, что толкает к приключениям и в итоге к кризису — но лишь затем, чтобы сдвинуть дело с мёртвой точки. Манифестируемый тип означает, что эмоции напрямую выходят в слова и действия и легко втягивают других. Через такую беспокойную страсть, по книге, взрослеет человечество и движется вперёд Коллектив.", "inner": "Человека ведёт поиск опыта, обещающего нечто новое и лучшее, а мудрость приходит только через практику. Колебания эмоциональной волны могут делать его ветреным или разочарованным, когда опыт не оправдал ожиданий. Корректным книга называет принятие своих эмоциональных качелей и время на ясное решение, особенно когда предстоящее тревожит, — а потом полное проживание опыта ради него самого. Со временем опыт созревает в личную истину, центр которой — принятие жизни такой, какая она есть, и умение «ловить мгновение».", "together": "Быть с другими для них значит проживать опыт вместе; тяга к новизне и знание, что ничто не вечно, усложняют долгую близость, а партнёры страдают, если их втянули в неподходящие приключения. Чувства здесь вызваны самим опытом, а не другим человеком, так что разочарованными могут остаться оба. В электромагнитной паре (35-е у одного, 36-е у другого) стабильность отношений зависит от гребней эмоциональной волны.", "plain": "Вас тянет пробовать новое, и многое вы узнаёте только на собственном опыте. Вы ярко рассказываете о пережитом и вдохновляете этим других. Перед тем как нырнуть в очередное приключение, стоит дать чувствам успокоиться.", "practice": ["Какие мои прошлые «прыжки» в новое оказались ценными, а какие — нет, и чем отличались решения?", "Как мои поиски новых впечатлений сказываются на близких людях?"]}, "37-40": {"name": "Канал Сообщества", "design": "Дизайн Части, ищущей целое", "type": "Проецируемый", "page": 248, "classic": "Канал Сообщества, дизайн Части, ищущей целое, соединяет 37-е ворота Дружбы в Солнечном Сплетении с 40-ми воротами Одиночества в Сердце. Книга кладёт сообщество в основу успешной эволюции человечества. В Контуре Эго Племенной группы этот канал отвечает за сделку: 40-е ворота готовы работать ради близких, но ждут вознаграждения и отдыха, 37-е с даром привязанности ищут своё место в целом. Здесь работают два мотора: эмоции дают ясность со временем, Эго — волю довести договорённость до конца, поэтому хорошая сделка не заключается спонтанно, её вынашивают, чтобы она была равно выгодна обеим сторонам. Канал проецируемый и построен на оппозиции ворот в Мандале, поэтому встречается довольно часто. Книга связывает с ним большое эволюционное влияние в текущем цикле через Правоугольный Крест Планирования.", "inner": "Человек ждёт, пока его позовут стать частью сообщества, и пытается понять, к чему он принадлежит. Корректное приглашение, по книге, приходит не через «холодный» контакт вроде звонка, а через личное «прикосновение», складывающееся со временем. Хотя каждый экзистенциально одинок, такой человек строит мост, по которому люди входят в общность, где у всех есть место и почётные обязанности. Он понимает цену хорошей сделки и умеет её скрепить: «Я сделаю это для вас, если вы окажете услугу мне. По рукам».", "together": "Это канал брачных уз: чтобы «поставщик» и «распространитель» жили в гармонии, нужна ясная и твёрдая договорённость. На этой стороне контура путь к сердцу лежит «через желудок, а не через бумажник» — поддержка выражается работой плечом к плечу, а не покупками. Высший идеал — сообщество почти без иерархии, где каждый вносит посильный вклад.", "plain": "Вам важно чувствовать, что вы часть своей группы, семьи или команды. Вы хорошо договариваетесь, но лучше не спешить с обещаниями, а дать себе время. В общность лучше входить через живой личный контакт, а не формально.", "practice": ["Где мои договорённости с людьми ясны и взаимны, а где кто-то из нас отдаёт больше?", "Как ощущается разница между приглашением через личный контакт и через формальный запрос?"]}, "39-55": {"name": "Канал Эмоциональности", "design": "Дизайн Перепадов настроения", "type": "Проецируемый", "page": 188, "classic": "Пульсирующая волна настроения «вкл/выкл» рождается в канале Эмоциональности, где 39-е ворота Провокации из Корневого центра встречаются с 55-ми воротами Духа в Солнечном Сплетении. Книга определяет его как провокацию ради усиления осознанности духа и называет дизайном Перепадов настроения. Это индивидуальная волна Контура Знания: в целом ровная, с внезапными пиками экстаза и меланхолии, механический континуум между счастьем и печалью, которому не нужно придумывать причин. Канал проецируемый: его влияние сильнее, когда человека распознали. По книге, перепадам этого канала подвержены все, а его глубокая творческая сила проявится на планете в 2027 году. Ключевой образ — чашка, которая одновременно наполовину пуста и наполовину полна, и слова Ра Уру Ху «Истинная духовность рождается из корректности».", "inner": "Человек умеет распознавать и провоцировать дух в других, чувствует, чьё настроение резонирует с его, и со временем учится находить своих людей. Его провокация открывает других к новому и выявляет в них то, чего они в себе не знали. Влияние зависит от настроения, но он не должен быть жертвой настроений и делать жертвами других. Когда настроения общаться нет, корректно, по книге, быть наедине с внутренней музой — это ведёт к зрелому эмоциональному творчеству и собственной правде.", "together": "Открываясь полному спектру своих эмоций, такие люди снижают напряжение в отношениях. Книга советует им не заниматься любовью, не есть и не работать «не в духе»: без настроения нет удовольствия. Без здорового отношения переменчивость может становиться манипулятивной, а меланхолию начинают глушить внешними удовольствиями.", "plain": "Ваше настроение может меняться волнами без видимой причины, и это нормально. Вы умеете «расшевелить» людей и почувствовать, кто вам по духу. Когда настроения нет, лучше побыть с собой, чем заставлять себя.", "practice": ["Пытаюсь ли я объяснить своё настроение причинами, которых на самом деле нет?", "Как люди реагируют на мои «провокации» — что в них открывается и что закрывается?"]}, "42-53": {"name": "Канал Созревания", "design": "Дизайн Сбалансированного развития", "type": "Генерируемый", "page": 218, "classic": "Канал Созревания, дизайн Сбалансированного развития, соединяет 53-е ворота Начинаний в Корневом центре с 42-ми воротами Роста в Сакрале. Книга называет его сердцевиной абстрактного эмпирического пути: войти в цикл, пройти его, завершить и отрефлексировать, чтобы извлечь мудрость. Это форматная энергия Контура Ощущений — её циклическая частота окрашивает все остальные ворота и каналы этого контура. Каждый новый опыт опирается на предыдущий, а оборванный раньше срока цикл придётся проходить снова. Канал генерируемый: энергия начать и довести до конца есть, когда вход идёт через отклик. Процесс не нацелен на достижение целей — жизнь здесь видится бесконечным путешествием, а коллективный опыт помогает человечеству умнеть быстрее, чем идёт биологическое развитие.", "inner": "Человеку важно, чтобы каждый опыт завершался с удовлетворением, — тогда можно оглянуться и только потом начинать новое. Осмысление прожитого вместе с другими открывает ценность уроков, и на этой основе рождается следующий опыт. Корректным книга называет вход через Стратегию и Авторитет; иначе можно застрять в цикле, к которому пропал интерес или который не удаётся закончить. Главная ловушка — ожидания: они делают уязвимым для разочарования и эмоционального крушения.", "together": "Такие люди сонастроены с физическими, социальными и природными циклами, им близка история. Цикл может длиться от нескольких часов до всей жизни; пройдя его до конца и отрефлексировав, человек делится опытом на общее благо.", "plain": "Для вас важно доводить начатое до конца и лишь потом браться за новое. Брошенные на полпути дела, скорее всего, вернутся снова. Чем меньше ожиданий вы вкладываете в процесс, тем легче он идёт.", "practice": ["Какие незавершённые дела или отношения я сейчас продолжаю носить с собой?", "С какими ожиданиями я начинаю новое и как они влияют на процесс?"]}, "47-64": {"name": "Канал Абстракции", "design": "Дизайн Ментальной активности, смешанной с ясностью", "type": "Проецируемый", "page": 228, "classic": "64-е ворота Замешательства в Теменном центре и 47-е ворота Реализации в Аджне образуют канал Абстракции — дизайн Ментальной активности, смешанной с ясностью. Это эмпирическая сила ума, которая перебирает калейдоскоп образов прожитого, включая несостоявшееся, пока что-то внезапно не всплывёт и не откроет смысл. Канал принадлежит абстрактному Контуру Ощущений Коллективной группы: его взгляд обращён в прошлое, а цель — понять опыт и найти историю, которой можно поделиться. Книга видит в соединении неокортекса и глубоких областей мозга потенциал сознания, способного рефлексировать само себя. Канал проецируемый, и его понимание ценнее всего, когда его просят. Важная оговорка книги: ум не может быть внутренним авторитетом и никогда не будет уверен ни в чём на сто процентов.", "inner": "Это очень активный ум, который непрерывно играет с возможностями; книга сравнивает его вихрь с «пьяной обезьяной, укушенной скорпионом». Замешательство может стать началом поиска того, что действительно имеет смысл: при терпении разрозненные точки сами соединяются в картину, а награда за ожидание ясности — вдохновляющая история или новая перспектива. Ловушка — пытаться решать этим умом собственные проблемы и постигать смысл собственной жизни: для этого он, по книге, совершенно не приспособлен.", "together": "Давление искать смысл ослабевает, когда человек находит способ делиться своим пониманием с другими. Его повествовательный ум может быть даром для историков, но опирается не на факты, а на переживание. Слушать, как такой ум приходит к своему «Ага!», по словам книги, захватывающе.", "plain": "Ваша голова постоянно перебирает картинки и воспоминания, и это может сбивать с толку. Если не торопиться, из этой путаницы складывается ясная и интересная история. Лучше делиться ею с другими, чем пытаться с её помощью решить все свои жизненные вопросы.", "practice": ["В каких ситуациях я пытаюсь «додумать» решение вместо того, чтобы опереться на что-то кроме ума?", "Что происходит с моим замешательством, когда я рассказываю о пережитом другому человеку?"]}};
  const GATE_BOOK={"1": {"iching": "Творческий", "name": "Ворота Самовыражения", "page": 179, "lines": ["Творчество независимо от воли", "Любовь — это свет", "Энергия для поддержания творческой работы", "Уединение как средство для творчества", "Энергия привлекать общество", "Объективность"], "classic": "Первые ворота G Центра — центра идентичности и направления — несут тему творческого самовыражения как самостоятельной силы. Ключевая фраза говорит о творчестве как о базовой энергии: потенциале проявлять вдохновение, не втискивая его в чужие рамки. Здесь нет стремления быть лучшим — такая гонка характерна для Коллективного; важнее прожить свою подлинную творческую природу. Увлечённый своим делом, носитель этих ворот часто не замечает, сколько внимания к себе притягивает. Влияние раскрывается, когда он остаётся верен собственному процессу: новые способы выражения «я» открывают другим иные перспективы и порой меняют их творческое направление. Корректное проживание книга связывает с тем, чтобы быть увиденным и оценённым, — то есть с взаимодействием с миром и ожиданием приглашения.", "plain": "Это тема желания выражать себя по-своему, а не соревноваться. Когда вы делаете то, что вам по-настоящему интересно, это само по себе вдохновляет окружающих. Важно, чтобы вашу работу заметили и позвали, — тогда она находит своих людей.", "partner": "С 8-ми воротами рядом оказывается тот, кто умеет продвигать плоды творчества. Без них продавать свою работу самому обычно наименее приятная задача, поэтому человека часто тянет к людям с 8-ми воротами.", "special": "", "practice": "Когда вы в последний раз создавали что-то, не думая о том, лучше ли это, чем у других, — и что при этом заметили окружающие?"}, "2": {"iching": "Восприимчивый", "name": "Ворота Направления «Я»", "page": 177, "lines": ["Интуиция", "Гений", "Терпение", "Скрытность", "Разумное применение", "Фиксация"], "classic": "В G Центре 2-е ворота отвечают за внутренний компас: здесь расположен Магнитный Монополь, или Водитель, который ведёт человека во времени и пространстве. «Высшее знание» этих ворот — собственное направление к любви и красоте, и понимается оно шире географии. Ключевая фраза описывает восприимчивость как исходную основу любого отклика и действия; книга сравнивает ворота с ключом зажигания, заводящим двигатель. Изменить это направление умом или усилием воли нельзя, и если окружающим нужно в другую сторону, дороги могут разойтись. Носитель часто подсказывает другим путь к нужным ресурсам и, следуя своему направлению, пробуждает в людях чувство их собственного. Его роль — стратег, который даёт план или обзор нового пути, а не исполнитель чужой работы.", "plain": "Это тема внутреннего чувства «куда мне идти». Его нельзя придумать головой — оно просто есть, и когда вы ему следуете, другим тоже легче найти свой путь. Вы скорее показываете направление, чем делаете работу за других.", "partner": "Топливо для движения в своём направлении приходит из Сакрального центра через 14-е ворота: к людям с ними обращаются как к союзникам, чтобы получить силу и ресурсы для своего видения.", "special": "Здесь находится место Водителя — Магнитного Монополя; характерный образ ворот — «ключ зажигания».", "practice": "В каких ситуациях вы ловите себя на том, что подсказываете кому-то, куда двигаться, — и что вы сами в этот момент чувствуете о собственном пути?"}, "3": {"iching": "Трудности в начале", "name": "Ворота Упорядочивания", "page": 175, "lines": ["Синтез", "Незрелость", "Выживание", "Харизма", "Преследование", "Сдача"], "classic": "Сакральный центр даёт этим воротам жизненную силу для трудной задачи — превзойти хаос и навести порядок, чтобы новое и жизнеспособное смогло закрепиться в мире. Название «Трудности в начале» отражает суть: инициация всегда начинается с замешательства. Ворота связаны с уникальным индивидуальным знанием и способностью внести инновационный вклад, но правильного момента для мутации приходится ждать, и это ожидание порой тянется бесконечно. Творческий пульс работает в режиме «вкл/выкл», его нельзя предсказать, ускорить или подчинить логике и опыту. Время «выкл» в этой системе — не пустота, а период, чтобы углубиться в свой процесс наедине с музой. Если не ждать, тяга к переменам скорее расшатывает окружающих; а тот, кто входит в ауру в нужный момент, может измениться, даже если носитель ничего особенного не делает.", "plain": "Это тема наведения порядка там, где пока всё запутано, и привнесения нового. Перемены здесь приходят рывками, в своё время, и торопить их бесполезно. Периоды затишья — нормальная часть процесса, а не признак, что с вами что-то не так.", "partner": "Энергия для мутации приходит импульсами из 60-х ворот: их выбросы случайны, и к непредсказуемости их тайминга нужно относиться с терпением.", "special": "Когда кажется, что энергии для перемен нет, может накатывать меланхолия или даже депрессия.", "practice": "Как вы обычно проживаете периоды, когда ничего нового не происходит, — и что в них на самом деле созревает?"}, "4": {"iching": "Безрассудство Юности", "name": "Ворота Формулирования", "page": 213, "lines": ["Удовольствие", "Принятие", "Безответственность", "Лгун", "Соблазнение", "Избыток"], "classic": "Ворота Формулирования в Аджне настраивают ум на вопросы, полные сомнения о будущем, и превращают их в логичные ответы. Ключевая фраза звучит парадоксально — энергия быть привлекательным и успешным, несмотря на невежество: формула может понравиться ещё до того, как её подтвердят. Каждый ответ здесь лишь потенциал, который предстоит проверить фактами; он может оказаться тем, что люди ищут, а может и нет. Давление сомнений способно сопровождать всю жизнь, поэтому книга советует опираться на свой Авторитет — он подскажет, на каких вопросах сосредоточиться, пока не пришло время делиться. Ответы этих ворот предназначены прежде всего другим: для собственных жизненных вопросов человек находит подходящие формулы редко. Принятие этого приносит покой — ответы приходят и уходят, пока не поступит приглашение их высказать.", "plain": "Это тема умения находить объяснения и ответы, особенно на вопросы о будущем. Чаще всего ваши ответы полезнее другим, чем вам самим, — и это нормально. Не каждую идею нужно сразу озвучивать: лучше дождаться, когда о ней спросят.", "partner": "63-и ворота поставляют вопросы и сомнения, на которые отвечают 4-е. Без них можно долго искать следующий вдохновляющий вопрос или тревожиться, что жизнь всегда будет хаотичной.", "special": "Характерное беспокойство — что в жизни никогда не наступит порядок; в книге оно связано с отсутствием 63-х ворот.", "practice": "Какие ответы приходят вам легко, когда спрашивают другие, — и как часто вы пытаетесь применить их к своей жизни?"}, "5": {"iching": "Ожидание", "name": "Ворота Фиксированных паттернов", "page": 205, "lines": ["Настойчивость", "Внутренний покой", "Принуждение", "Охотник", "Радость", "Податливость"], "classic": "Здесь ожидание понимается не как пауза, а как активное состояние сознания — книга сравнивает его с беременностью. Энергия Сакрального центра в этих воротах любит фиксированные ритмы и даёт стойкость держаться своего внутреннего распорядка. Именно в нём человек остаётся здоровым, полным сил и в потоке; бытовые ритуалы приносят глубокое удовлетворение и, по формулировке книги, сонастраивают с «вибрациями всей жизни». Ключевая фраза говорит о базовой сонастройке с естественными ритмами. Вынужденные отклонения от них выбивают из равновесия физически, психологически и эмоционально. Поэтому книга советует не сомневаться в своих ритмах и не поддаваться соблазну отступить от них под чужим влиянием.", "plain": "Это тема привычного распорядка и своего темпа. Режим, ритуалы, порядок дня здесь не скучная рутина, а источник сил. Когда вас сбивают с ритма, это может ощущаться сильнее, чем у других.", "partner": "Трение возникает с людьми, у которых 15-е ворота: их меняющийся ритм может подрывать ваш режим. Книга советует не «исправлять» их своей фиксированностью — гибкость помогает им оставаться здоровыми, а взаимное понимание снимает противоречие.", "special": "", "practice": "Какие ежедневные ритуалы дают вам ощущение устойчивости, и что происходит, когда их приходится нарушать?"}, "6": {"iching": "Конфликт", "name": "Ворота Трения", "page": 237, "lines": ["Отступление", "Партизан", "Лояльность", "Триумф", "Арбитраж", "Миротворец"], "classic": "Солнечное Сплетение — эмоциональный центр, и 6-е ворота порождают все три его режима: чувства, настроения и чувствительность. Эта «моторизованная» комбинация волн создана производить трение, и ключевая фраза формулирует закон: без трения нет роста. Трение даёт жар для плодотворности, направлено на 59-е ворота и возникает механически, когда человек входит в чужую ауру. Книга сравнивает ворота с диафрагмой, которая открывает или закрывает путь к близости, и называет их воротами pH-баланса — границы между тем, что снаружи, и тем, что внутри тела. Поэтому здесь решается, кого и когда подпускать близко и какую роль человек будет играть в отношениях. Когда конфликт разрешён, проход открывается и близость углубляется, но готовность зависит от эмоциональной волны, и проводниками служат Стратегия и Авторитет.", "plain": "Это тема эмоциональной границы: кого и когда вы готовы подпустить ближе. Напряжение и споры здесь — часть роста, а не поломка. Решения о близости лучше не принимать на пике чувств, а дать им отстояться.", "partner": "Из-за страха близости 6-е ворота ищут 59-е — их способность ломать барьеры открывает путь к сближению.", "special": "Как все ворота Солнечного Сплетения, они несут страх — здесь это страх близости.", "practice": "Что вы замечаете в себе, когда кто-то быстро сокращает дистанцию, — и как меняется ваше отношение к этому человеку спустя время?"}, "7": {"iching": "Армия", "name": "Ворота Роли «Я»", "page": 207, "lines": ["Автократ", "Демократ", "Анархист", "Отрекающийся", "Генерал", "Администратор"], "classic": "Логические ворота направления в G Центре, часть Правоугольного Креста Сфинкса, смотрят в будущее и замечают, когда курс общества пора поправить. Ключевая фраза называет их точкой конвергенции и говорит о потребности в лидерстве, которое ведёт и наводит порядок. Вклад в Коллективное выражается через шесть ролей, совпадающих с названиями линий: Автократ, Демократ, Анархист, Отрекающийся от престола, Генерал, Администратор. Книга описывает их как генетические, «механические» роли с сильным обусловливающим действием. Опираясь на свою роль и понимание будущего направления, человек убеждает других и влияет даже на влиятельных — особенно на носителей 31-х ворот. Он может пересматривать существующий паттерн или сомнительный курс либо стать катализатором нового, занимая позицию «серого кардинала».", "plain": "Это тема умения видеть, куда стоит двигаться группе или обществу. Часто такое влияние идёт не с трибуны, а через советы тем, кто стоит впереди. Ваш стиль руководства может сильно отличаться от стиля других людей с той же темой.", "partner": "Через 31-е ворота видение получает публичный голос. Без них человек может быть лидером, но не обязательно публичной фигурой, напрямую влияющей на Коллективное.", "special": "", "practice": "Когда ваши соображения о том, куда двигаться, действительно повлияли на решение группы, — кто их в итоге озвучил?"}, "8": {"iching": "Сплочение", "name": "Ворота Вклада", "page": 179, "lines": ["Честность", "Служение", "Фальшивка", "Уважение", "Дхарма", "Причастность"], "classic": "В Горловом центре эти ворота звучат голосом: «Я знаю, что могу (или не могу) внести вклад». Ключевая фраза описывает базовую ценность — индивидуальное усилие, вложенное в цели группы. Вклад приходит двумя путями: через публичную демонстрацию собственного образа жизни, направления и творений либо через продвижение чужого творчества. Образ книги — владелец галереи или арт-агент, который привлекает внимание ко всему новому и оригинальному, а затем ведёт примером, постепенно меняя ориентацию Коллективного и Племени. Индивидуальное новшество не приживается, пока его не поддержат и не встроят в общее. Путь того, кто распознаёт мутационное, бывает одиноким: сначала нужно признание, затем приглашение показать то, что ценно для будущего; без приглашения реакция может быть отрицательной.", "plain": "Это тема желания сделать свой особый вклад — показать миру что-то новое, своё или чужое. Вы можете быть тем, кто замечает и продвигает необычное. Лучше всего это работает, когда вас сначала признали и позвали.", "partner": "С 1-ми воротами вклад опирается на собственное творческое самовыражение. Если их нет, ключевая роль — быть не художником, а агентом, продвигающим новое видение других.", "special": "Голос ворот: «Я знаю, что могу (или не могу) внести вклад».", "practice": "Что нового или необычного вам хочется показать другим прямо сейчас, — и кто уже проявил к этому интерес?"}, "9": {"iching": "Укрощающая Сила Малого", "name": "Ворота Фокуса", "page": 203, "lines": ["Здравомыслие", "Нищета любит компанию", "Последняя капля, переполняющая чашу", "Самоотверженность", "Вера", "Благодарность"], "classic": "Ворота Фокуса работают как воронка: собирают огромную мощь 52-х ворот на том, что действительно важно. Сакральный центр даёт им настойчивость долго удерживать внимание на всех деталях проекта или вопроса, как следует проверяя и оценивая формулы. Ключевая фраза связывает реализацию потенциала с детальным вниманием к каждому существенному аспекту. Книга подчёркивает, что успех логики человечества как вида во многом зависит от этой энергии. Результат можно передать Коллективному или применить в собственной жизни. Чистая, сфокусированная аура помогает тем, кто рядом, эффективнее тратить физическую и ментальную энергию.", "plain": "Это тема сосредоточенности на деталях. Вы можете долго и тщательно заниматься одним делом, проверяя мелочи. Рядом с таким вниманием и другим легче собраться.", "partner": "52-е ворота дают долгую усидчивость. Без них её не всегда хватает для концентрации, и это может стать источником фрустрации.", "special": "", "practice": "На каких деталях ваше внимание задерживается само собой, а где удерживать его приходится через силу?"}, "10": {"iching": "Поступь", "name": "Ворота Поведения «Я»", "page": 167, "lines": ["Скромность", "Отшельник", "Мученик", "Оппортунист", "Еретик", "Ролевая модель"], "classic": "Одни из самых сложных ворот G Центра входят в Инкарнационный Крест Чаши Любви и названы воротами любви к себе. Ключевая фраза говорит о внутреннем кодексе поведения, который обеспечивает успешное взаимодействие при любых обстоятельствах. Шесть линий — это шесть возможностей поведения, шесть собственных ролей, в которых человечество может узнать, что значит жить как девятицентровая самоосознающая форма с потенциалом пробуждения. На языке системы пробуждение — не решение стать кем-то, а решимость стать собой, и без принятия себя оно невозможно. Принимая то, что делает его уникальным, и входя в жизнь с уважением к своей форме, человек усиливает любовь к себе и в других. Книга отмечает, что акцент на принятии себя способен заметно повлиять на движение человечества в XXI веке.", "plain": "Это тема того, как вы ведёте себя и насколько принимаете себя таким, какой вы есть. Речь не о том, чтобы стать «правильным», а о том, чтобы быть собой. Когда вы относитесь к себе с уважением, окружающим тоже становится легче принимать себя.", "partner": "Шесть ролей поведения направляются интуицией 57-х ворот, усиливаются сакральным откликом 34-х и выражаются через 20-е.", "special": "Ворота любви к себе; одни из четырёх ворот Инкарнационного Креста Чаши Любви.", "practice": "В каких ситуациях вы ведёте себя так, как «положено», а не так, как вам свойственно, — и что при этом чувствуете?"}, "11": {"iching": "Покой", "name": "Ворота Идей", "page": 231, "lines": ["Настройка", "Строгость", "Реалист", "Учитель", "Филантроп", "Приспособляемость"], "classic": "Ворота Идей в Аджне превращают прочувствованное в идеи и концепции. Ключевая фраза описывает состояние покоя, которое даёт время для оценки перед новым действием. В этой точке абстрактного процесса появляется тишина, чтобы собрать отсортированные воспоминания, прошедшие через взлёты и падения опыта: запоминается то, что по-настоящему понравилось, остальное отпускается. Так идеи становятся идеалами, затем верованиями и системами верований. Человек ищет чужие идеи, которые подстёгивают его размышления, и сам избирательно стимулирует других. До Горла идеи доходят как слова, а не как действие: попытки решать ими собственные дилеммы ведут к фрустрации и замешательству, зато смаковать детали прошлого ради самого процесса — большое удовольствие.", "plain": "Это тема множества идей и образов. Идеи приходят и уходят, и не каждая из них — инструкция к действию. Ими приятно делиться и обсуждать их, но решения лучше принимать иначе.", "partner": "56-е ворота помогают рассказать историю вовремя. Без них может возникать импульсивное давление делиться своими историями, не дожидаясь подходящего момента.", "special": "", "practice": "Какая из ваших недавних идей вдохновила вас больше всего, — и пытались ли вы превратить её в план, не дожидаясь подходящего случая?"}, "12": {"iching": "Бездействие", "name": "Ворота Осторожности", "page": 191, "lines": ["Монах", "Очищение", "Исповедь", "Пророк", "Прагматик", "Метаморфозы"], "classic": "Индивидуальный эмоциональный голос Горлового центра здесь сдерживается естественной осторожностью. Ключевая фраза подчёркивает ценность сдержанности, медитации и бездействия перед лицом соблазна. Человек склонен молчать, пока настроение не подскажет, что есть что сказать — по-своему и трансформирующе; важнее подбора слов оказываются тон и звучание голоса. Молчание и созерцание своих чувств дают посланию созреть, чтобы затем выразиться в творческом настроении — например, в поэзии или музыке. Сильнее всего воздействие «случайного незнакомца»: артиста, который выразил радости и печали жизни и ушёл за кулисы. Вне настроения слушатели вряд ли уловят суть, а точный тайминг усиливает влияние на социальные и культурные нормы.", "plain": "Это тема осторожности в словах и умения ждать нужного настроения, чтобы высказаться. Когда вы говорите в правильный момент, ваши слова трогают людей. Если настроения нет, лучше помолчать.", "partner": "С 22-ми воротами чувства обретают ясность. Без них человек знает, как себя выразить, но не всегда может разъяснить, что именно чувствует.", "special": "Характерная роль — «случайный незнакомец». В описании канала 22-12 с этими воротами связывают мутацию гортани около 85 000 лет назад.", "practice": "Замечаете ли вы разницу в том, как воспринимают ваши слова, когда вы в настроении говорить и когда говорите через силу?"}, "13": {"iching": "Братство людей", "name": "Ворота Слушателя", "page": 223, "lines": ["Эмпатия", "Фанатизм", "Пессимизм", "Усталость", "Спаситель", "Оптимист"], "classic": "Звено преемственности между прошлым и будущим — так можно описать роль 13-х ворот G Центра. Их дар — слушать, замечать и хранить чужие тайны. Ключевая фраза говорит об универсальных идеях и ценностях, собранных в упорядоченную структуру, которая вдохновляет на гуманистическое сотрудничество. Люди сами рассказывают носителю этих ворот о пережитом: он любит истории, приключения, победы и проблемы и легко удерживает услышанное в себе. Давления говорить здесь нет; важно распознать момент, чтобы передать самые ценные воспоминания тем, кто сумеет их отобрать, осмыслить и донести до широкого круга. Так уроки практического опыта сохраняются, пока не станут вкладом в осознание человечества.", "plain": "Это тема умения слушать и хранить чужие истории. Людям часто хочется вам довериться. Со временем вы можете передать накопленный опыт тем, кто сумеет им распорядиться.", "partner": "33-и ворота умеют упорядочить опыт и рассказать о нём широкому кругу. Без них секреты могут так и остаться нераскрытыми.", "special": "", "practice": "Какие истории, которые вам доверили, кажутся вам по-настоящему ценными, — и кому их было бы уместно передать?"}, "14": {"iching": "Владение в Великой Мере", "name": "Ворота Силовых навыков", "page": 177, "lines": ["Деньги это не все", "Управление", "Служение", "Безопасность", "Высокомерие", "Смирение"], "classic": "Сакральный центр здесь работает как «педаль газа»: решает, когда и как расходовать ресурсы. Ворота усиливают и индивидуальное направление, и направление человечества, распределяя доступные ресурсы и показывая более широкие горизонты для их вложения. Ключевая фраза говорит о накоплении и удержании силы через умелое взаимодействие, соединяющее изящество с контролем. Плодородная сила ворот — это способность определённого Сакрала часами поддерживать творческую работу. Занимаясь любимым делом в согласии со своим дизайном, человек создаёт богатство и силу, но, по книге, распоряжается ими как управляющий: они нужны для поддержки индивидуального творчества, благотворительности или лидеров, ведущих в будущее. Разбрасывать деньги куда попало — не вложение; чтобы энергия не застаивалась и ею не злоупотребляли, важно следовать своему Авторитету.", "plain": "Это тема рабочей силы и ресурсов, включая деньги. Когда вы заняты любимым делом, энергия и средства приходят легче. Важно, куда вы их направляете, — лучше туда, на что откликается ваше нутро.", "partner": "Ресурсы, которыми грамотно распоряжаются 2-е ворота с их направлением, могут стать значительным катализатором перемен в мире.", "special": "Образ ворот — «педаль газа».", "practice": "Во что вы вкладываете своё время и деньги с ощущением, что это действительно ваше, — и где ловите себя на тратах по инерции?"}, "15": {"iching": "Скромность", "name": "Ворота Крайностей", "page": 205, "lines": ["Долг", "Влияние", "Инфляция эго", "Застенчивость", "Чувствительность", "Самозащита"], "classic": "Любовь к человечеству в 15-х воротах G Центра — это способность принять весь спектр человеческого поведения и найти каждому проявлению место в обществе. Ключевая фраза говорит о поведении, которое выражает нужный баланс между крайностями. Фиксированного паттерна здесь нет, и это открывает пространство для самых разных видов любви. Речь не о том, как мы соединяемся с конкретными людьми, а о трансперсональной любви к разнообразию, которая начинается с любви к собственным крайностям — например, десять часов сна в одну ночь и два в другую. Магнитный Монополь усиливает притягательность ауры. Под руководством Авторитета растёт способность влиять на экстремальные ритмы так, что они становятся умеренными и встраиваются в Коллективное.", "plain": "Это тема меняющихся ритмов и принятия разных людей. Ваш режим может сильно колебаться — и это не обязательно проблема. Вам свойственно находить место для самых разных проявлений человеческой природы.", "partner": "5-е ворота дают дисциплинированный фиксированный ритм. Без них собственные вечно меняющиеся ритмы могут рассеивать фокус, нужный для мастерства в какой-то области.", "special": "", "practice": "Какие свои крайности в режиме или поведении вам проще всего принять, а какие вы до сих пор пытаетесь «исправить»?"}, "16": {"iching": "Энтузиазм", "name": "Ворота Навыков", "page": 211, "lines": ["Иллюзия", "Циник", "Независимость", "Лидер", "Вредина", "Легковерие"], "classic": "Горловой центр в 16-х воротах выражает навык, доведённый до искусства. Ключевая фраза говорит о великом искусстве обогащать жизнь гармоничным течением энергии. Со временем человек может производить впечатление острого критика, умелого оратора или того, кто полон таланта и энтузиазма к жизни, но начинается всё иначе. Сначала нужно отождествиться с навыком и посвятить себя повторению и практике, пока мастерство не превратит умение в искусство; книга говорит об этом так: «мир ждёт момента, когда танцор станет танцем». Человек ищет идеальный способ выразить свою квалификацию и источник материальной поддержки, чтобы сосредоточиться на совершенствовании и сделать результат доступным другим. Глубину, форму и направление его практике дают люди с 48-ми воротами.", "plain": "Это тема умений, которые оттачиваются повторением. Энтузиазм здесь — начало, а мастерство приходит через практику. Вам важно найти, где и как применять свой талант, и поддержку, чтобы его развивать.", "partner": "48-е ворота придают навыку глубину и поддерживают практику. Без них человек может быть самокритичным и ощущать нехватку глубины.", "special": "", "practice": "Какой навык вы готовы повторять снова и снова без внешней награды, и что мешает вам практиковать его регулярно?"}, "17": {"iching": "Следование", "name": "Ворота Мнений", "page": 215, "lines": ["Открытость", "Дискриминация", "Понимание", "Менеджер по персоналу", "Человек не остров", "Бодхисаттва"], "classic": "Среди множества концепций и мнений Аджна 17-х ворот ищет то, которому можно довериться: оно должно выдержать проверку и критику и унять страхи перед будущим. Ворота структурируют ответы в концепции, рабочие паттерны и возможные решения и готовят их к детальному подтверждению 62-ми воротами. Ключевая фраза опирается на древний закон: кто желает править, должен уметь служить. На этом отрезке логического процесса мнения сопровождаются сомнениями о будущем. Правый глаз воспринимает мир как набор узнаваемых визуальных паттернов, а то, что не выдержало проверки логикой, должно быть отброшено. При этом перевести увиденную картину в слова удаётся не всегда.", "plain": "Это тема мнений и того, как вы видите мир — сразу целыми картинами и схемами. Ваше мнение полезно, когда его проверили и о нём спросили. Иногда трудно объяснить словами то, что вам очевидно.", "partner": "62-е ворота переводят концепцию в язык и снабжают её фактами и деталями. Без них человек ищет названия для своих концепций, факты в поддержку мнений и способы выразить свои предположения.", "special": "Характерная тревога — страх, что никто не поймёт и не оценит вклад.", "practice": "Как вы проверяете собственное мнение, прежде чем его высказать, — и что происходит, когда вы делитесь им без запроса?"}, "18": {"iching": "Работа над испорченным", "name": "Ворота Исправления", "page": 209, "lines": ["Консерватизм", "Смертельный недуг", "Фанатик", "Некомпетентность", "Терапия", "Состояние Будды"], "classic": "Селезёночная осознанность 18-х ворот с удовольствием находит, называет и оспаривает всё, что нуждается в исправлении. Ключевая фраза говорит о бдительности и решимости защищать базовые права человека. Неудовлетворённость здесь служит сигналом: если что-то раздражает, оно, вероятно, утратило жизненность, а за этим стоит глубокая забота о здоровье и гармонии общества. Дар критического сознания ведёт к источнику слабости и направляет мысль на способы исправления или замены, опираясь на беспристрастную проницательность и отточенный логический анализ. Это коллективные ворота: их критика уместна на уровне ситуаций, паттернов и систем. В личных отношениях, отмечает книга, она обычно приносит лишь неприятности.", "plain": "Это тема умения замечать, что работает плохо, и желания это улучшить. Ваш взгляд особенно ценен, когда касается дел, порядков и систем. Критика личных черт людей обычно приносит больше вреда, чем пользы.", "partner": "58-е ворота дают топливо — «радость исправления». Без них неудовлетворённость может превратиться в постоянный поиск ошибок, особенно если внимание смещается с ситуаций на манеры и недостатки людей.", "special": "Страх ворот — страх авторитетов и страх бросить им вызов.", "practice": "Когда вам хочется что-то исправить, на что направлено ваше внимание — на порядок дел или на конкретного человека?"}, "19": {"iching": "Подход", "name": "Ворота Потребности", "page": 247, "lines": ["Взаимозависимость", "Служение", "Вовлечённость", "Командный игрок", "Жертва", "Затворник"], "classic": "Корневой центр даёт 19-м воротам давление, связанное с двумя сущностными потребностями: доступом к базовым ресурсам — еде, крову — и доступом к духу. Ключевая фраза говорит о том, что всё взаимосвязано и проявляется через подход; именно эти потребности, по книге, готовят нас к отношениям с другими. Когда у каждого есть еда, жильё и «свой бог», сообщество живёт здорово и поддерживает своих, а нехватка и сильное неравенство разрушают эту поддержку. Носитель ворот чувствителен к тому, в чём отказано его семье, сообществу и обществу, и несёт другим осознание того, что нужно каждому для выживания и процветания. Как именно это проявится, зависит от линии. Обычно это требует войти в доверие или заключить договор с теми, кто разделяет его принципы и располагает ресурсами.", "plain": "Это тема чуткости к нуждам — своим и чужим: что людям нужно для нормальной жизни. Вы можете остро замечать, кому чего не хватает. Важно найти тех, кто разделяет ваши принципы и может помочь ресурсами.", "partner": "Человек знает, что необходимо, и ищет 49-е ворота, чтобы эти потребности были удовлетворены.", "special": "Если давление Корня обращается на себя, возможны гиперчувствительность, навязчивое желание быть нужным или чрезмерная потребность в окружающих — с внутренним вопросом «Когда уже позаботятся обо мне?».", "practice": "Чьи нужды вы замечаете раньше других, — и как отличаете заботу о сообществе от собственной потребности быть нужным?"}, "20": {"iching": "Созерцание", "name": "Ворота Настоящего", "page": 165, "lines": ["Поверхностность", "Догматизм", "Самосознание", "Применение", "Реализм", "Мудрость"], "classic": "Чистая экзистенциальность — так книга характеризует 20-е ворота Горлового центра. Их энергия растворена в текущем моменте, не учитывает ни прошлого, ни будущего и обеспечивает способность к собственному выживанию. Ключевая фраза говорит о распознавании и осознанности в моменте, которые превращают понимание в правильное действие. Осознанность может стать словом или действием, но только в подходящее время. Человек редко обдумывает то, что в нём бурлит, поэтому его слова и поступки внезапны для всех, включая его самого: он видит, когда не смотрит, и слышит, когда не слушает. В этом скрыт потенциал эволюционного изменения; живя по Стратегии и Авторитету и полностью присутствуя в моменте, человек становится примером и усиливает других.", "plain": "Это тема жизни здесь и сейчас. Слова и действия могут рождаться спонтанно, удивляя даже вас самих. Чем больше вы присутствуете в настоящем, тем точнее срабатывают такие моменты.", "partner": "Через 20-е ворота голос получают интуиция выживания 57-х, принципы поведения 10-х и сакральная сила 34-х, которая проявляется в действии.", "special": "Диапазон выражения ворот — от «Я есть сейчас» до «Я знаю, что я делаю сейчас».", "practice": "Какие ваши спонтанные слова или поступки оказались самыми точными, — и в каком состоянии вы тогда были?"}, "21": {"iching": "Прогрызание", "name": "Ворота Охотника/Охотницы", "page": 251, "lines": ["Предостережение", "Сильный человек всегда прав", "Бессилие", "Стратегия", "Объективность", "Хаос"], "classic": "Центр Сердца, или Эго, наделяет 21-е ворота потребностью контролировать свою сферу деятельности. Ключевая фраза говорит об оправданном применении силы против намеренного и постоянного вмешательства. Чтобы направить волю ради выживания Племени, человеку нужно что-то или кого-то контролировать — в современном мире это, например, полномочия управляющего или президента компании. Книга называет «прогрызание» мощной обусловливающей силой материальной жизни. Успех приходит, когда человек сам решает, где жить, что носить, на кого работать; указаний он не любит. Вместе с тем он призван служить, и в племенной сделке выигрывает не только он. Попытка захватить власть без Стратегии и Авторитета встречает яростное сопротивление, поэтому важно дождаться, пока контроль предложат.", "plain": "Это тема желания самому распоряжаться своей жизнью, деньгами и делами. Вам может быть трудно, когда вами командуют. Лучше всего управление получается, когда его вам доверили, а не когда вы его взяли.", "partner": "С 45-ми воротами контроль соединяется с заботой о благосостоянии группы. Без них человек может искать ситуации, где мог бы присматривать за будущим сообщества.", "special": "Книга даёт указания по типам: Проектора должны распознать и пригласить управлять, Генератора — спросить, чтобы получить доступ к его энергии, а Манифестору стоит проинформировать, прежде чем взять контроль.", "practice": "В каких сферах жизни вам важно решать самому, — и как на ваш контроль реагируют люди, которые о нём не просили?"}, "22": {"iching": "Грация", "name": "Ворота Открытости", "page": 191, "lines": ["Билет 2-го класса", "Школа шарма", "Чародей", "Чувствительность", "Прямота", "Зрелость"], "classic": "Эмоциональная открытость через слушание соединяется в 22-х воротах Солнечного Сплетения с социальным изяществом и шармом. Ключевая фраза говорит о поведении, которое лучше всего подходит для обыденных повседневных ситуаций. В хорошем настроении человек очень привлекателен; при смене волны проявляется другая сторона — драматичная, порой асоциальная. Погружаясь в глубины своей волны и давая правде созреть рядом с творческой музой, он оттачивает чувство момента, когда общество готово её услышать. Открытость и внимание к тому, что ново для других, действуют даже на незнакомцев: он слушает, пока собеседник не договорит, отодвигая собственную потребность говорить. Книга называет ответственностью и привилегией использовать это умение, чтобы делать перемены доступными другим.", "plain": "Это тема обаяния и умения слушать. В хорошем настроении вы легко располагаете к себе, в плохом — лучше дать себе время. Ваше внимание к собеседнику само по себе многое для людей значит.", "partner": "12-е ворота помогают выразить чувства словами. Без них человек может знать, что чувствует, но не знать, как это сказать.", "special": "Главный страх — что сейчас нечего услышать стоящего, отсюда раздражение тишиной. В описании канала добавлено: эти ворота слышат левым ухом и только то, что хотят слышать.", "practice": "Как меняется ваша готовность общаться и слушать в зависимости от настроения, — и учитываете ли вы это, планируя встречи?"}, "23": {"iching": "Расщепление на части", "name": "Ворота Ассимиляции", "page": 183, "lines": ["Обращение в другую веру", "Самозащита", "Индивидуальность", "Фрагментация", "Ассимиляция", "Синтез"], "classic": "Внутреннее знание в 23-х воротах Горлового центра наконец переводится в язык. Ключевая фраза говорит об отсутствии морализаторства и о понимании, ведущем к принятию разнообразия; вместе со способностью прорываться сквозь ментальную ограниченность это открывает мутации путь в общество. Это уникальный голос «Я знаю»: то, что человек знает или не знает, притягивает внимание, но может и отдалять. Трансформирующие озарения требуют ясного изложения сути. Если его перспективу уважают, остаётся дождаться момента и объяснить просто; иначе есть риск прослыть чудаком. Книга советует говорить только то, что действительно знаешь, — тогда со временем этот своеобразный гений получит признание.", "plain": "Это тема необычных прозрений и умения объяснить их просто. Ваши мысли могут сильно отличаться от общепринятых. Лучше всего их слышат, когда вас сами спросили и вы говорите коротко и ясно.", "partner": "43-и ворота поставляют концептуальное озарение. Без них появляется беспокойство: удастся ли ясно выразиться, поймут ли, не отвергнут ли.", "special": "Голос ворот — «Я знаю»; при несвоевременных объяснениях есть риск прослыть фриком.", "practice": "Когда ваши необычные идеи принимали лучше всего, — каким был момент и в какой форме вы их высказали?"}, "24": {"iching": "Возвращение", "name": "Ворота Рационализации", "page": 181, "lines": ["Грех упущения", "Признание", "Наркоман", "Отшельник", "Исповедь", "Дареный конь"], "classic": "Задача 24-х ворот Аджны — принять уникальное вдохновение 61-х ворот и превратить его в рациональную концепцию, которой можно поделиться. Ключевая фраза описывает естественный, спонтанный процесс трансформации и обновления. Ум снова и снова возвращается к одним и тем же мыслям, пока не облечёт их в форму, но не может действовать из вдохновения или объяснять его логикой и прошлым опытом: знания то нет, то вдруг оно есть. Книга советует позволять себе возвращаться и пересматривать — перечитывать, смотреть и слушать что-то по нескольку раз. Если не пытаться контролировать ум, ответ часто приходит сам — как «АГА» в тишине, посреди ночи.", "plain": "Это тема мыслей, которые крутятся по кругу, пока не сложатся в понимание. Возвращаться к одному и тому же по много раз — нормальный для вас способ разобраться. Озарение часто приходит, когда вы перестаёте его искать.", "partner": "61-е ворота поставляют вдохновение для осмысления. Без них появляется давление принимать решения от ложного «я» в погоне за разгадками бесконечных тайн.", "special": "Страх невежества — тревога, что никогда не удастся узнать что-то наверняка или объяснить своё знание; он обостряется, когда человек пытается решать умом.", "practice": "К каким мыслям вы возвращаетесь снова и снова, — и в какие моменты к вам приходили неожиданные ответы?"}, "25": {"iching": "Невинность", "name": "Ворота Духа «Я»", "page": 197, "lines": ["Бескорыстие", "Экзистенциалист", "Чувствительность", "Выживание", "Исцеление", "Невежество"], "classic": "Ворота Высшего «Я» в G Центре несут любовь, которая вытекает из полного принятия формы и сдачи ей. Ключевая фраза говорит о совершенстве действия, рождённого естественностью и спонтанностью. Главная роль ворот — разворачивать людей к индивидуализации. Невинность здесь — любовь без различий: способность любить жизнь и всё в ней в равной мере, цветок так же, как человека; такую любовь часто принимают за прохладную, хотя книга с этим не согласна. Человек встречает инициации жизни как духовный воин, готовый отстаивать свой дух, свою индивидуальность, при любых обстоятельствах. Пройдя испытание, даже израненным, он обретает мудрость, которая обогащает и его, и окружающих; итог — жизнь, полная удивления и любви к существованию.", "plain": "Это тема открытой, ровной любви ко всему живому и умения сохранять себя в испытаниях. Ваша доброжелательность может казаться другим сдержанной, хотя она просто широкая. Трудности здесь закаляют и делают мудрее.", "partner": "51-е ворота, «воин или дурак», подталкивают прыгнуть в пустоту; 25-е способны приземлиться и устоять, углубляя свою невинность.", "special": "Ворота Высшего «Я»; их универсальная любовь без различий часто кажется «холодной».", "practice": "Какое жизненное испытание сильнее всего изменило вас, — и что в вас осталось неизменным после него?"}, "26": {"iching": "Укрощающая Сила Великого", "name": "Ворота Эгоиста", "page": 245, "lines": ["Синица в руке", "Уроки истории", "Влияние", "Цензура", "Адаптивность", "Авторитет"], "classic": "Центр Сердца в 26-х воротах соединяет энергию эго с талантом работать с памятью. Ключевая фраза говорит о максимальном усилении силы памяти ради непрерывности. Прошлое здесь избирательно фильтруется, чтобы отвлечь от страхов; граница между правдой и вымыслом размывается, а потенциал подаётся как реальность и «продаётся» публике за определённую цену. Это прирождённый продавец, способный преувеличивать и растапливать недоверие. Если такие навыки признают и предлагают работу со своим графиком, хорошим вознаграждением и временем на отдых, человек охотно занимает первые позиции в Племени. Ждать признания и давать только выполнимые обещания — способ сохранить влияние, а верность своим принципам, по книге, укрепляет и эго, и здоровье сердца.", "plain": "Это тема умения убеждать и красиво подавать — себя, идею, товар. Ваш талант лучше всего раскрывается, когда его ценят и достойно вознаграждают. Важно обещать только то, что вы действительно можете выполнить.", "partner": "44-е ворота дают инстинктивную осознанность. Без них трудно понять, как, когда и что эффективно передавать.", "special": "", "practice": "Где проходит для вас граница между удачной подачей и преувеличением, — и как вы чувствуете, что её перешли?"}, "27": {"iching": "Вскармливание", "name": "Ворота Заботы", "page": 239, "lines": ["Эгоизм", "Самодостаточность", "Жадность", "Щедрость", "Исполнитель", "Осторожность"], "classic": "Сакральная энергия 27-х ворот направлена на заботу: поддерживать и улучшать качество жизни юных, слабых и больных. Ключевая фраза говорит о том, что забота повышает качество и суть любых действий. В воротах огромный потенциал альтруизма; книга приводит пример Матери Терезы. Роль человека — вскармливать через дар сострадания, он неравнодушен. Но то же нужно делать и для себя: сначала позаботиться о себе, чтобы хватало сил и ресурсов на других, а где и когда отдавать, подсказывает Авторитет. Забота без осознанности, по книге, — растрата драгоценных ресурсов; каждая линия описывает свой способ заботы и связи с Племенем.", "plain": "Это тема заботы о других — особенно о тех, кто слабее. Чтобы помогать долго, важно не забывать о себе. Не каждая просьба о помощи — ваша: прислушайтесь к себе, прежде чем откликнуться.", "partner": "50-е ворота дают чувство ценностей и меры. Без них трудно ставить здоровые границы своим порывам заботиться, и это легко оборачивается жертвой собственным благополучием.", "special": "", "practice": "Когда вы в последний раз заботились о ком-то в ущерб себе, — и что подсказывало ваше тело до того, как вы согласились?"}, "28": {"iching": "Преобладание Великого", "name": "Ворота Игрока", "page": 185, "lines": ["Подготовка", "Рукопожатие дьявола", "Авантюризм", "Удержание", "Предательство", "Вспышка славы"], "classic": "Упрямая энергия 28-х ворот Селезёночного центра сосредоточена на слушании, которое помогает интуитивно понять, какие риски делают жизнь по-настоящему живой. Название «Ворота Игрока» отражает суть: с бдительностью селезёночной осознанности человек способен играть на грани так, как другие не решаются, и однажды может неожиданно встретиться со страхом смерти. Ключевая фраза напоминает о мимолётности власти и влияния. Сквозная тема ворот — борьба за смысл жизни. Их энергия может развернуть наружу людей с каналом 57-20, сделав их интуитивное знание доступным. Осознанность 28-х помогает носителям 38-х ворот решать, во что вкладывать силы, и распознавать здоровые и безопасные цели для борьбы.", "plain": "Это тема поиска смысла и готовности рисковать ради того, что действительно важно. Вы можете идти туда, куда другие не решаются. Важно выбирать борьбу, которая стоит ваших сил.", "partner": "Без 38-х ворот легко попасть под ненужное давление бороться и истощиться в лишнем сопротивлении; поэтому человек тянется к людям с 38-ми, чтобы понять, что стоящего они нашли в своей борьбе.", "special": "Самый глубокий страх ворот — что жизнь закончится раньше, чем удастся понять её ценность и смысл.", "practice": "Ради чего вы готовы рисковать и бороться, — и как отличаете осмысленную борьбу от сопротивления по привычке?"}, "29": {"iching": "Бездна", "name": "Ворота Настойчивости", "page": 221, "lines": ["Призывник", "Оценивание", "Оценка", "Прямота", "Превышение", "Замешательство"], "classic": "Сакральное «да» 29-х ворот — источник постоянного жизнеутверждения: оно направляет энергию к новому человеку или делу и стойко проводит через весь цикл открытий. Ключевая фраза — «глубина в глубине»: упорство в трудностях ведёт к неизбежной награде. Настойчивость при этом циклична: то, что увлекало сегодня, завтра может перестать интересовать. Каждое обязательство помогает созреть потенциалу и показывает, кто человек в отношениях с людьми и миром. Из-за нетерпеливой готовности соглашаться лучше дождаться ясности, куда вложить силы: сакральный отклик механичен, и куда заведёт путь, заранее неизвестно. Пройти через трудности помогает только полная сонастроенность с решением, а единственная гарантия, по книге, — отпустить ожидания и положиться на Стратегию и Авторитет.", "plain": "Это тема согласия и упорства: сказав «да», вы готовы вкладываться до конца. Поэтому важно, на что вы соглашаетесь, — лучше не торопиться. Интерес может приходить и уходить волнами, это нормально.", "partner": "46-е ворота придают усилиям смысл и направление. Без них человек готов работать, но не знает, ради чего.", "special": "", "practice": "На что вы согласились слишком быстро за последнее время, — и что подсказывало ваше первое внутреннее ощущение?"}, "30": {"iching": "Цепляющийся Огонь", "name": "Ворота Чувств", "page": 225, "lines": ["Самообладание", "Прагматизм", "Смирение", "Выгорание", "Ирония", "Принуждение"], "classic": "Эмоциональная волна Солнечного Сплетения в 30-х воротах окрашена желанием. В описании они названы также Воротами Судеб и учат, что жизнь — не то, чего мы от неё ждём, а то, чем мы позволяем ей быть. Ключевая фраза — свобода, признанная иллюзией, и ограничение, принятое как судьба. Опыт начинается с желания, которое встречается с жизнью на подъёмах и спадах волны и может ощущаться как одержимый голод, пока не будет утолён — и то лишь на время. Под контролем человека только ясность, с которой он входит в новый опыт; результат ему не подвластен. Равновесие приходит через сдачу и принятие того, что есть, и тогда размышления о чувствах и желаниях становятся даром для других.", "plain": "Это тема сильных желаний и ожиданий от жизни. Чувства здесь бывают очень яркими, поэтому в новое лучше входить, когда эмоции улеглись. Результат часто оказывается не таким, как представлялось, — и в этом тоже есть опыт.", "partner": "Фантазии 41-х ворот питают желание; книга советует не поддаваться подавленности в погоне за ними.", "special": "Без ясности жизнь, по книге, превращается в бешеные эмоциональные скачки; судьбы не стоит бояться, а неразделённое желание — принимать на свой счёт.", "practice": "Какое ваше сильное желание сбылось не так, как вы ожидали, — и что вы из этого опыта вынесли?"}, "31": {"iching": "Влияние", "name": "Ворота Лидерства", "page": 207, "lines": ["Манифестация", "Высокомерие", "Избирательность", "Намерение", "Самодовольство", "Применение"], "classic": "Горловой центр в 31-х воротах создан для влияния и говорит голосом «Я веду». Ключевая фраза описывает закон трения, активного или пассивного, которое вызывает передачу и тем самым влияние. Коллективное лидерство здесь коллегиально, а не иерархично: оно даёт видение нового направления и показывает путь, но не проходит его за людей. Голос не будет услышан, пока его не поддержит энергия большинства и люди не начнут действовать на основе сказанного, — поэтому влияние проявляется через электорат. Такое лидерство должно учитывать желания последователей и приносить пользу целому; оно может работать и на благо, и во вред. Книга предупреждает: когда на позицию власти продвигают деньги, а не дух сотрудничества, способность общества обеспечивать будущее искажается.", "plain": "Это тема лидерства, которое держится на поддержке людей. Вас слушают, когда вас выбрали и признали. Хороший лидер здесь показывает путь, а не тащит всех за собой.", "partner": "7-е ворота дают понимание направления. Без них голос лидера может звучать пусто.", "special": "Голос ворот — «Я веду» (или «Я вас веду»).", "practice": "В каких ситуациях к вашим словам действительно прислушивались, — и что этому предшествовало?"}, "32": {"iching": "Преемственность", "name": "Ворота Непрерывности", "page": 243, "lines": ["Сохранение", "Ограничение", "Недостаток непрерывности", "Кто прав, тот и Могущественен", "Гибкость", "Спокойствие"], "classic": "Инстинктивная оценка — суть 32-х ворот Селезёночного центра: постоянное распознавание того, что можно трансформировать, а что нет. Ключевая фраза утверждает, что постоянны только изменения. Способность адаптироваться, сохраняя свою природу, — вклад Селезёнки в материальную преемственность Племени. Один из даров — замечать тех, у кого есть навыки для роста, и представлять их людям, обладающим властью. Человек склонен напряжённо размышлять о балансе между тем, что уже работает, и риском перемен; когда баланс найден, рост оптимален. Опираясь на свой Авторитет и инстинкты, он помогает обществу не повторять неработающее и сохранять то, что остаётся ценным.", "plain": "Это тема чутья к тому, что стоит сохранить, а что пора менять. Вы можете долго взвешивать, прежде чем решиться. Ваше умение замечать перспективных людей и проверенные решения — ценный вклад.", "partner": "54-е ворота дают устойчивое топливо, драйв и амбиции. Без них 32-м не хватает энергии, чтобы преуспевать.", "special": "В основе ворот лежит страх неудачи, способный притормаживать амбиции; книга называет их также воротами длительной нерешительности.", "practice": "В каком решении вы сейчас колеблетесь между привычным и новым, — и что подсказывает ваше первое инстинктивное ощущение?"}, "33": {"iching": "Ретрит", "name": "Ворота Уединения", "page": 223, "lines": ["Уклонение", "Сдача", "Дух", "Достоинство", "Тайминг", "Разобщение"], "classic": "Ворота Уединения стоят в Горловом центре, где прожитое обретает форму высказывания, и отмечают точку, где один цикл уже закончился, а следующий ещё не начался. В этой паузе возникает неуверенность и потребность отойти в тишину: перебрать каждый аспект пережитого, восстановить силы и решить, что взять с собой дальше. Ключевая фраза об активном уходе говорит, что отступление здесь не бегство: именно оно превращает слабую позицию в сильную. В тихом размышлении поднимаются самые ценные уроки из Коллективной памяти, и со временем человека просят поделиться ими — тогда его опыт, свой, чужой или общий, становится частью общества. Образ книги — Блудный сын, который растёт всю жизнь и с каждым новым кругом расширяет своё влияние.", "plain": "Эта тема про умение уйти в тишину, когда что-то в жизни закончилось. Вам может требоваться время наедине, чтобы разобраться, что произошло и чему это научило. Позже такие выводы часто становятся ценными для других людей.", "partner": "Соединение с 13-ми воротами даёт чувство момента, когда пора делиться своими уроками; без них этого ощущения времени может не хватать.", "special": "Голос ворот — «Я помню»: здесь живёт потребность пересказывать уроки пережитого и открывать заключённые в нём истины.", "practice": "Когда очередной этап моей жизни заканчивается, даю ли я себе время на тишину, прежде чем браться за новое?"}, "34": {"iching": "Сила Великого", "name": "Ворота Силы", "page": 163, "lines": ["Задира", "Импульс", "Мачо", "Триумф", "Аннигиляция", "Здравый смысл"], "classic": "Сакральный центр — главный жизненный мотор Бодиграфа, и 34-е ворота несут из него, пожалуй, самую впечатляющую силу: энергию, которая поддерживает человека на пути к собственной уникальности. От остальных восьми сакральных ворот их отличают две вещи — они асексуальны, и их мощь не предназначена для других. Окружающие могут восхищаться этой силой и даже тянуться к ней, но она должна оставаться чистой и доступной самому человеку — для его независимости и следования собственным убеждениям. Ключевая фраза напоминает, что величие силы раскрывается, когда её проявление служит общему благу. Корректное проживание книга связывает с триумфом, который считает точным признаком того, что человек живёт свою жизнь.", "plain": "Это тема мощной личной энергии, которой хватает, чтобы много делать и держаться своего пути. Ваша сила работает лучше всего, когда вы тратите её на своё, а не отдаёте тем, кто хочет ею воспользоваться. Признак, что всё идёт верно, — ощущение победы, а не изнеможения.", "partner": "С 10-ми воротами сила поддерживает поведение и роли, верные убеждениям, с 20-ми — превращается в дело, с 57-ми — в чуткое умение слышать, что нужно для выживания в моменте. Без интуитивной координации Селезёнки эта неутомимая энергия может стать навязчивой, импульсивной и уходить впустую, оставляя чувство потерянности.", "special": "Особая пометка: ворота асексуальны, а их сила недоступна для других — этим они отличаются от прочих сакральных ворот.", "practice": "На что сегодня ушла моя энергия — на моё собственное дело или на то, чего от меня ждали другие?"}, "35": {"iching": "Прогресс", "name": "Ворота Перемен", "page": 227, "lines": ["Смирение", "Творческий кризис", "Сотрудничество", "Голод", "Альтруизм", "Исправление"], "classic": "Здесь, в Горловом центре, живёт жажда перемен: огромное любопытство и высокие надежды тянут исследовать новые горизонты, причём обязательно вместе с другими — ключевая фраза прямо говорит, что прогресс невозможен в вакууме. Двигает человека не столько осознанность, сколько вызванный эмоциональной волной голод по глубокому чувству, а такой голод утоляется лишь на время. Интерес направлен на приключения, из которых можно чему-то научиться, а не на повторение и шлифовку; мастерство здесь превращается в мудрость и советы, а воспоминания порой радуют сильнее, чем сам опыт. Тяга узнать, что «за углом», помогает оставаться бодрым и бдительным. В языке системы корректно входить в опыт ради него самого и с позиции наблюдателя — тогда ясный рассказ о прожитом способен менять людей.", "plain": "Это тема любопытства и тяги к новым впечатлениям. Вам может быть скучно повторять одно и то же, а интереснее пробовать новое — и потом рассказывать, чему это научило. Ваш опыт может стать полезным советом для других.", "partner": "Без 36-х ворот появляется склонность гнаться за эмоциональными пиками, чтобы сбежать от тягостной скуки, и при этом мало думать о последствиях своих поступков.", "special": "Голос ворот — «Я чувствую»; чаще всего он чувствует желание перемен и говорит от лица неличностного опыта отношений.", "practice": "Когда меня тянет к новому опыту, что я ищу — само переживание или способ уйти от скуки?"}, "36": {"iching": "Затмение Света", "name": "Ворота Кризиса", "page": 227, "lines": ["Сопротивление", "Поддержка", "Переход", "Шпионаж", "Андеграунд", "Справедливость"], "classic": "Солнечное Сплетение — центр эмоциональной волны, и в 36-х воротах эта волна «надежда–боль» особенно сильна. Здесь страхи неопытности и уязвимости, эмоциональные и сексуальные, превращаются в опыт: человек встречает и порой сам создаёт вызовы, которые через кризис ведут к переменам и росту. Ключевая фраза о законе циклов напоминает, что упадок — естественная, но не вечная стадия. Энергия ворот направлена к Горлу, весь диапазон чувств готов прорваться наружу, и не хватает лишь того, кто «щёлкнет переключателем». С эмоциональной ясностью приходит умение спокойно встречать чужие кризисы и реже устраивать свои; книга советует позволять чувствам проявляться, даже неудобным, потому что только так достигается глубина, открывающая внутреннюю истину.", "plain": "Это тема сильных чувств и жизненных кризисов, через которые приходит рост. Вам может казаться, что эмоции накатывают волнами и требуют выхода. Со временем появляется умение пережидать спады, зная, что они проходят.", "partner": "35-е ворота дают энергии выход и направление; без них происходящее может восприниматься как личный кризис, а ощущение, что не удаётся воплотить свои надежды, — вызывать нервное беспокойство.", "special": "Страхи ворот — уязвимость и неопытность, эмоциональная и сексуальная; они смягчаются, превращаясь в прожитый опыт.", "practice": "Как я обычно веду себя на спаде своей эмоциональной волны — тороплю события или даю чувству пройти?"}, "37": {"iching": "Семья", "name": "Ворота Дружбы", "page": 249, "lines": ["Мать/Отец", "Ответственность", "Беспристрастность", "Лидерство через пример", "Любовь", "Цель"], "classic": "Книга называет 37-е ворота самыми «коммунальными» в Бодиграфе. Они принадлежат Солнечному Сплетению и строят эмоциональную связь через прикосновение, теплоту и особую чувствительность, которую окружающие считывают как открытость. Когда эту силу замечают, человек сплачивает семью и сообщество заботой и дружелюбием; его охотно видят тем, кто встречает новичков и незнакомцев, — и он соглашается, если условия справедливы и ясно оговорены всеми. Ключевая фраза об органической природе сообществ говорит, что одни и те же законы действуют и в семье, и в большом обществе. Это ещё и «ворота рта»: сбор и приготовление еды часто стоят в центре его семейной и общественной жизни, а в паре с 40-ми воротами он распределяет то, что приносит снабженец.", "plain": "Это тема тепла, дружбы и заботы о своих. Вам может быть естественно собирать людей за общим столом и поддерживать атмосферу семьи. Важно лишь, чтобы взаимные договорённости были понятны всем.", "partner": "Без 40-х ворот человек ищет тех, кто будет приносить сообществу нужные ресурсы, — чтобы было с кем договариваться и что распределять.", "special": "Главный страх — оказаться в ловушке традиционных семейных и племенных ролей; особая пометка ворот — «ворота рта».", "practice": "Ясно ли проговорено в моих близких отношениях, кто что даёт и что получает взамен?"}, "38": {"iching": "Оппозиция", "name": "Ворота Борца", "page": 185, "lines": ["Квалификация", "Учтивость", "Альянс", "Расследование", "Отчуждение", "Недопонимание"], "classic": "Ворота Борца питаются давлением Корневого центра и требуют от человека — и от тех, кто рядом, — найти цель в жизни: причину существовать, любовь и смысл, которые поднимают борьбу над простым выживанием. Ключевая фраза о сохранении целостности перед разрушительными силами описывает энергию противостояния, позволяющую выдерживать удары судьбы; хороший бой приносит ему удовольствие. Со стороны видна яростная независимость и упорство перед любым вызовом, хотя по сути человек ищет, ради чего жить. Жизнь обретает смысл, когда он заступается за тех, кто не может постоять за себя, если это для него корректно. Его упрямство помогает другим понять, какие битвы им важны, а умение отличать свою схватку от чужой открывает путь к осознанности 28-х ворот.", "plain": "Это тема борьбы за то, что для вас по-настоящему важно. Вам может нравиться отстаивать свою позицию и защищать других. Главный вопрос — какие сражения действительно ваши, а на какие жалко тратить силы.", "partner": "", "special": "Это одни из трёх ворот «глухоты»: они ограждают индивидуальность от чужого вмешательства и помогают не идти на навязанные компромиссы.", "practice": "За что из того, ради чего я сейчас борюсь, я действительно готов стоять — и что я защищаю просто по привычке?"}, "39": {"iching": "Препятствие", "name": "Ворота Провокации", "page": 189, "lines": ["Выход из боя", "Конфронтация", "Ответственность", "Сдержанность", "Целеустремленность", "Тот, кто решает проблемы"], "classic": "Провокация — главный инструмент этих ворот Корневого центра: их давление будит эмоциональную осознанность духа, и именно человек с 39-ми воротами пробуждает потенциал мутации в 55-х. Ключевая фраза говорит о ценности препятствия: столкновение заставляет анализировать, оценивать и пересматривать. Провоцируя, человек и сам соприкасается со своими чувствами и находит силу пробиться сквозь настроение к духу; а по реакции людей видно, кто его — если для кого-то он лишь раздражитель, это не его круг. Реакция бывает резкой, и, возможно, придётся нарастить «толстую кожу»; в плохом настроении такие провокации ранят. Книга подчёркивает, что передать настоящую, заразительную мутацию можно только будучи в духе, поэтому нужны время, терпение к себе и к своей эмоциональной волне.", "plain": "Это тема умения «расшевелить» людей — вопросом, шуткой или вызовом. Вам может быть свойственно задевать других, чтобы пробудить в них живое чувство. Со временем приходит понимание, кого и когда стоит так тревожить.", "partner": "55-е ворота помогают выпустить эмоции; без них давление Корня может толкать к крайностям — злоупотреблению едой, алкоголем или веществами.", "special": "Одни из трёх ворот «глухоты»: внешние влияния мало затрагивают такого человека.", "practice": "В каком настроении я обычно провоцирую людей — и чем отличается результат, когда я в духе и когда нет?"}, "40": {"iching": "Освобождение", "name": "Ворота Одиночества", "page": 249, "lines": ["Восстановление", "Решительность", "Смирение", "Организация", "Жёсткость", "Гильотина"], "classic": "В 40-х воротах Сердечный центр проявляет волю через труд и обещания. Здесь живёт чувство одиночества даже в окружении людей — начало индивидуализации, потребность отделиться от Племени, которую со стороны принимают за независимость или отстранённость. Это любовь к работе: выполняя корректное для себя дело и свои обещания признательному сообществу, человек получает глубокое удовлетворение и освобождается — об этом переходе от борьбы к освобождению и говорит ключевая фраза. Отношения строятся как сделка и требуют частых переговоров и прозрачности: доступ к заработанному получают те, кто соблюдает договорённости. Взамен ему нужны благодарность, лояльность, эмоциональная поддержка, еда и время на отдых в одиночестве.", "plain": "Это тема работы и обеспечения своих людей. Вам может нравиться много трудиться ради семьи или команды, но важно, чтобы это ценили. И ещё — вам нужно время, чтобы побыть одному и восстановиться.", "partner": "Без 37-х ворот человек может искать дружбу и сообщество, чтобы предложить им силу своего эго и взять на себя их обеспечение.", "special": "Одни из трёх ворот одиночества — вместе с 12-ми и 33-ми.", "practice": "Получаю ли я за свой труд то, что мне на самом деле нужно, — признание, поддержку, время на отдых?"}, "41": {"iching": "Уменьшение", "name": "Ворота Сжатия", "page": 225, "lines": ["Благоразумие", "Осторожность", "Эффективность", "Исправление", "Авторизация", "Инфекция"], "classic": "С 41-х ворот начинается человеческий путь опыта: давление Корневого центра проявляется как эмоциональный голод, желание чувственного взаимодействия с другими. Это может быть смутное ожидание, фантазия или острая потребность пережить с кем-то нечто новое, хотя неясно, что именно, когда и с кем, — исполнение остаётся в руках судьбы, связанной с 30-ми воротами. Расплывчатое нетерпение уравновешивается мечтами, книгами и кино. Ключевая фраза об ограничении ресурсов объясняет главное: здесь заключён весь потенциал человеческого опыта, но запустить можно только один опыт за раз. Каждый опыт, начатый через Стратегию и Авторитет, несёт надежду на новое чувство, и, отпуская ожидания, человек свободно переходит от одного к другому, не впадая в пессимизм.", "plain": "Это тема предвкушения и желания новых переживаний. Вам может хотеться чего-то нового, даже если трудно сказать, чего именно. Мечты и истории помогают прожить это ожидание, пока не придёт настоящий опыт.", "partner": "Без 30-х ворот есть ощущение желания, но нет понимания, чего именно хочется.", "special": "Особая пометка: в описании канала 41–30 гексаграмма 41 названа стартовым кодоном — с входом Солнца в эти ворота в январе начинается новый солнечный год.", "practice": "Чего я сейчас жду от будущего — и насколько эти ожидания мешают мне радоваться тому, что происходит?"}, "42": {"iching": "Увеличение", "name": "Ворота Роста", "page": 219, "lines": ["Диверсификация", "Идентификация", "Пробы и ошибки", "Посредник", "Самореализация", "Питание"], "classic": "Сакральная энергия 42-х ворот — это упорство довести цикл до конца и раскрыть заложенный в нём потенциал. Рост здесь опирается на накопленный опыт: каждый новый цикл строится на уроках прошлого, а в конце человек подводит итоги. Ключевая фраза о расширении ресурсов связана с тем, что потенциал раскрывается полностью, только если прежний цикл закрыт, — иначе незавершённое всплывёт в новом, особенно в отношениях, где можно застрять в детских шаблонах. Фокус — на завершении, поэтому слабое или плохо поддержанное начало вызывает дискомфорт. В языке системы вход особенно важен: из начатого выйти трудно (книга приводит пример неудачного брака), и ожидание отклика через Стратегию и Авторитет даёт наибольший «потенциал удовлетворения».", "plain": "Это тема доведения дел до конца. Вам может быть важно завершать начатое и подводить итоги, прежде чем браться за новое. Поэтому стоит внимательно выбирать, во что ввязываться.", "partner": "53-и ворота дают стартовую искру; без них может не хватать энергии завершить процесс или накапливаться досада от попыток начать то, что невозможно продолжить.", "special": "", "practice": "Какой цикл в моей жизни остаётся незакрытым и может мешать мне начать новый?"}, "43": {"iching": "Прорыв", "name": "Ворота Озарения", "page": 183, "lines": ["Терпение", "Посвящение", "Целесообразность", "Ум, одержимый одной идеей", "Прогрессия", "Прорыв"], "classic": "Ворота «внутреннего уха» находятся в Аджне и слушают только собственный уникальный голос. Они превращают внутреннее знание в индивидуальное озарение — внезапный прорыв к новому взгляду, который не опирается на привычные факты. Ключевая фраза о новом справедливом порядке подразумевает, что такой прорыв меняет правила, поэтому нужно мужество «выйти из строя» и объяснять знание, которое кажется странным и не вписывается в коллективные нормы. В нужный момент человек способен придать своей осознанности завершённую мысленную форму, а затем инсайту предстоит спуститься к 23-м воротам Горла, чтобы принести миру мутацию. Труднее всего ему слушать других, и книга подчёркивает: это не вина, а генетическая защита от чужого влияния.", "plain": "Это тема внезапных догадок и оригинальных идей. Вам могут приходить мысли, которые сначала кажутся странными окружающим. Им нужно время и подходящий момент, чтобы вы смогли их ясно объяснить.", "partner": "Без 23-х ворот трудно выразить свой прорыв словами.", "special": "Страх ворот — быть отвергнутым: тревога, что идею не удастся объяснить или её сочтут слишком странной.", "practice": "Когда ко мне приходит новая идея, жду ли я подходящего момента, чтобы о ней рассказать, или выкладываю сразу?"}, "44": {"iching": "Идущий навстречу", "name": "Ворота Бдительности", "page": 245, "lines": ["Условия", "Менеджмент", "Вмешательство", "Честность", "Манипуляция", "Отстранённость"], "classic": "Перед нами ворота памяти Селезёнки: они запоминают паттерны, которые обеспечивают жизнь материальными ресурсами, — систематизированную часть видового «разума выживания». Человек инстинктивно бдителен к спонтанным встречам и связям, способным превратить потенциал в возможность; ключевая фраза говорит, что успех такого взаимодействия держится на отсутствии предварительных условий. То, что он помнит и передаёт, задаёт материальную ориентацию Племени: через него определяется, как 26-е ворота продают, защищают и отстаивают честь сообщества, — по книге, здесь рождается племенная пропаганда. Он помогает ослабить страхи прошлого, напоминая, что голодный ребёнок — нездоровый ребёнок. Поскольку Селезёнка не мотор, для перемен ворота опираются на волю Сердечного центра через 26-е.", "plain": "Это тема чутья на людей и возможности. Вам может быть свойственно с первой встречи понимать, с кем стоит иметь дело. Вы помните, что когда-то сработало, и это помогает вашему окружению быть в достатке.", "partner": "Без 26-х ворот можно без нужды брать на себя лишние обязательства и давать обещания, которые не получится выполнить.", "special": "Страх ворот — что настигнет багаж прошлого.", "practice": "Какой старый опыт влияет на то, как я сейчас встречаю новых людей и предложения?"}, "45": {"iching": "Собор", "name": "Ворота Собирателя", "page": 251, "lines": ["Предвыборная агитация", "Согласие", "Исключение", "Направление", "Лидерство", "Пересмотр"], "classic": "Короля или Королеву книга видит именно в 45-х воротах Горлового центра — единственном голосе Племени, который говорит «Я имею». Это глубоко эгоистичные ворота манифестации: Собиратель защищает материальные ресурсы сообщества, он его естественный авторитет и проводник, но не тот, кто сам работает. Ключевая фраза о притяжении похожих сил описывает его умение собирать людей вокруг общих потребностей, расширять сообщество и приносить гармонию; когда то, чем он «владеет», служит всем, в «королевстве» мир. Реальное управление делами остаётся за 21-ми воротами. Образ книги: король владеет землёй, но позволяет 21-м охотиться на ней, договорившись, что лучший кусок достаётся ему, — напряжение возникает, когда кто-то из них лезет не на своё место.", "plain": "Это тема лидерства и распоряжения общими благами. Вам может быть естественно объединять людей и представлять их интересы. Но повседневное управление часто лучше доверить тому, кто умеет это делать.", "partner": "", "special": "Особая пометка: даже если 21-е ворота есть в собственной карте, «королевством» или бизнесом эффективнее управлять с помощью чужих 21-х.", "practice": "Где я пытаюсь сам вести все дела вместо того, чтобы доверить управление другому и оставить за собой роль собирающего?"}, "46": {"iching": "Выталкивание наверх", "name": "Ворота Решительности «Я»", "page": 221, "lines": ["Быть обнаруженным", "Примадонна", "Проекция", "Воздействие", "Шаг", "Цельность"], "classic": "Центр G, где живут любовь и направление, в 46-х воротах обращён к телу. Это ворота качества жизни в физической форме: любви к телу и уважения к нему как к храму, благодаря которому человек оказывается в нужном месте в нужное время. Ключевая фраза об улыбке фортуны говорит, что удача, кажущаяся случайной, на деле рождается из усилия и самоотдачи. Ворота описывают абстрактный процесс сдачи циклу опыта, который может раскрыть потенциал или принести хаос; мудрость возникает из решимости и полной погружённости в происходящее. Проживание своей природы во взаимодействии с другими книга называет глубоко духовным процессом, ценность которого видна лишь по завершении цикла.", "plain": "Это тема бережного отношения к своему телу и доверия жизненному пути. Вам может везти, когда вы полностью отдаётесь делу. Смысл пережитого часто становится понятен лишь в конце.", "partner": "Без 29-х ворот может быть чувство времени, но не хватать энергии начать процесс или упорства довести его до конца.", "special": "Особая пометка: если не приспосабливаться к циклической природе жизни, тело начинает слабеть под грузом постоянных кризисов.", "practice": "Как я обращаюсь со своим телом в периоды, когда жизнь идёт не по плану?"}, "47": {"iching": "Подавление", "name": "Ворота Реализации", "page": 229, "lines": ["Оценка запаса", "Амбиция", "Самоподавление", "Репрессия", "Святой", "Тщетность"], "classic": "Если 64-е ворота — беспорядочный набор кадров, то 47-е в Аджне — монтажёр, который пытается собрать из них осмысленный фрагмент человеческого опыта. Полная картина не видна сразу: при сортировке образов неясно, в каком осколке ключ, а с каждой новой деталью человек колеблется между разными версиями событий. Ключевая фраза описывает это ощущение стеснённости — от внутренней слабости, от внешнего давления или от обоих сразу; поначалу процесс может казаться всё более запутанным. Но если отступить на шаг и довериться циклам, рано или поздно приходит момент «ага». Секрет, по книге, — не действовать после каждого вывода, а наслаждаться потоком возможностей в уме, пока что-то не прояснится, и делиться картиной, если об этом просят.", "plain": "Это тема осмысления пережитого. Вам может требоваться время, чтобы сложить разрозненные впечатления в понятную историю. Ясность приходит сама, если не торопить её.", "partner": "Без 64-х ворот можно давить на себя и не дожидаться откровения, которое дало бы уму передышку.", "special": "Особая пометка: давление действовать после каждого промежуточного вывода стоит игнорировать.", "practice": "Когда я не могу понять, что произошло, тороплю ли я вывод — или позволяю картине сложиться самой?"}, "48": {"iching": "Колодец", "name": "Ворота Глубины", "page": 211, "lines": ["Незначительность", "Дегенерация", "Визоляции", "Реорганизация", "Действие", "Самореализация"], "classic": "Колодец — образ 48-х ворот Селезёнки, где осознанность укоренена в инстинктивной памяти и даёт глубину для реальных, практичных решений общественных проблем. Ключевая фраза о качественной основе подчёркивает: прежде чем строить общее благо, нужен надёжный фундамент. Больше всего человек хочет выразить свою глубину и поделиться ею, чтобы помочь другим распознавать, исправлять и улучшать мир. Расслабленное активное ожидание притягивает тех, кто способен эту глубину раскрыть. Тогда решения проявляются естественно и ясно, становясь основой для оценки и совершенствования навыков у других и для наставничества.", "plain": "Это тема глубоких знаний и умения находить решения. Вам может казаться, что вы знаете недостаточно, хотя в вас много понимания. Лучше всего ваша глубина раскрывается, когда вас о ней спрашивают.", "partner": "Без 16-х ворот может возникать чувство неадекватности, досада от необходимости ждать, пока глубину заметят, и тревога из-за навыков, которых будто бы не хватает.", "special": "Страх ворот — чувство неадекватности и боязнь, что не удастся объяснить своё решение.", "practice": "Где я откладываю дело, считая, что ещё недостаточно знаю, хотя понимания у меня уже хватает?"}, "49": {"iching": "Революция", "name": "Ворота Принципов", "page": 247, "lines": ["Закон необходимости", "Последняя надежда", "Народное недовольство", "Платформа", "Организация", "Притяжение"], "classic": "Принципы принятия и отвержения, брака и развода, а в пределе и революции рождаются в 49-х воротах Солнечного Сплетения как следствие жизни в племенных иерархиях, подвластных эмоциональной волне. Ворота ставят человека на вершину такой иерархии, отсюда потребность в соблюдении правил и энергия решать: принять или отвергнуть, открыть доступ к ресурсам или призвать к переменам. Чуткость к людям и животным зависит от того, резонируют ли они с его принципами, — в близкий круг входят те, кто их разделяет. Ключевая фраза описывает идеал: менять формы ради высших принципов, а не ради власти. Он олицетворяет социальный план реформ, сосредоточенный на еде и её распределении: сытые не идут воевать, и революции можно избежать, удовлетворив потребности.", "plain": "Это тема принципов и выбора, с кем вы в одной лодке. Вам может быть важно, чтобы люди рядом разделяли ваши ценности. Ваше «да» или «нет» способно многое изменить для других.", "partner": "", "special": "Страх ворот — отвержения и непредвиденных последствий; это нервозность эмоциональных ворот.", "practice": "На каких принципах держатся мои решения принять или отвергнуть человека — и на какой точке эмоциональной волны я их принимаю?"}, "50": {"iching": "Котел", "name": "Ворота Ценностей", "page": 239, "lines": ["Иммигрант", "Решительность", "Приспособляемость", "Коррупция", "Последовательность", "Лидерство"], "classic": "Хранитель — так мистически называют 50-е ворота Селезёнки. Отправная мысль: любая близость, ведущая к рождению детей, требует, чтобы потомство доросло до зрелости, и в роли Племенного законодателя человек определяет, что хорошо и что плохо, — так правила заботы становятся основой морального воспитания. Движимая страхом Селезёнка даёт наказ защищать молодых и задавать им ориентиры. Ключевая фраза говорит о преемственности: традиционные ценности питают настоящее и будущее. Инстинктивная осознанность тщательно проверяет, что испорчено или несправедливо, что эгоистично и требует вызова, — это его способ заботиться о жизни сообщества, а линия уточняет, какие ценности и законы он распознаёт.", "plain": "Это тема ценностей, правил и заботы о младших. Вам может быть естественно следить, чтобы в семье или коллективе всё было справедливо. Важно не брать на себя больше ответственности, чем вы готовы нести.", "partner": "Без 27-х ворот человек может навязывать заботу там, где это для него некорректно, и сталкиваться со страхом ответственности, с которым трудно справиться.", "special": "Страх ворот — страх ответственности, поскольку Селезёнка движима страхом.", "practice": "За кого я сейчас взял ответственность — и было ли это моим решением или ощущением, что «так надо»?"}, "51": {"iching": "Пробуждение", "name": "Ворота Шока", "page": 197, "lines": ["Опора", "Уход", "Адаптация", "Ограничение", "Симметрия", "Отделение"], "classic": "Сердечный центр с его волей и мужеством в 51-х воротах становится энергией Индивидуальной инициации через шок. Это состязательная сила: быть на шаг впереди и рискнуть оказаться там, где никто не бывал, чтобы найти своё место. Ключевая фраза о способности откликнуться на беспорядок и шок говорит, что человек создан и выдерживать встряски, и встряхивать других — выводить их из коконов самоуверенности к трансценденции и любви к себе. Его заряжают любовь к жизни и постоянное соперничество. Обратная сторона мужества — безрассудство, которое ставит под удар уязвимое сердце, поэтому книга советует действовать через Стратегию и Авторитет, проверять, есть ли воля вступать в битву, и давать сердцу отдых.", "plain": "Это тема смелости и неожиданных поворотов. Вам может быть свойственно встряхивать других и самому быстро приходить в себя после потрясений. Важно не рисковать без нужды и давать себе передышку.", "partner": "Без 25-х ворот человек может искать «царство духа» ради руководства и направления.", "special": "Особая пометка: безрассудство несёт риск для сердца, физический и духовный, поэтому сердцу нужен отдых.", "practice": "После каких столкновений с миром мне требуется восстановление — и даю ли я его себе?"}, "52": {"iching": "Сохранение покоя", "name": "Ворота Неподвижности", "page": 203, "lines": ["Думай, прежде чем говоришь", "Забота", "Контроль", "Самодисциплина", "Объяснение", "Умиротворение"], "classic": "Гора — образ 52-х ворот Корневого центра, сырой мощи концентрации под давлением. Это пассивное напряжение, ищущее выход в 9-х воротах; внутри самих ворот разрядить его нельзя, можно только сфокусировать. Ключевая фраза описывает временное, наполненное энергией бездействие, которое нужно для оценки. Когда находится дело, с которым можно глубоко отождествиться и которое стоит вложений, давление двигаться вперёд уравновешивается способностью оставаться неподвижным и сосредоточенным. Пока этого нет, человек может метаться между чрезмерной активностью и упадком, так и не входя в спокойное собранное состояние.", "plain": "Это тема сосредоточенности и умения замереть, чтобы всё обдумать. Вам может быть трудно, когда нет дела, на котором хочется сфокусироваться. Найдя его, вы способны работать долго и спокойно.", "partner": "Без 9-х ворот и сакрального отклика трудно понять, на каком деле или деталях стоит сосредоточиться.", "special": "Особая пометка: пока баланс не найден, давление Корня может раскачивать между излишней деятельностью и подавленностью.", "practice": "Есть ли сейчас занятие, в которое мне хочется вложить своё внимание целиком?"}, "53": {"iching": "Развитие", "name": "Ворота Начинаний", "page": 219, "lines": ["Аккумуляция", "Импульс", "Практичность", "Убежденность", "Утверждение", "Фазы"], "classic": "Ворота Начинаний несут давление Корневого центра запустить циклический процесс созревания — от рождения до завершения. Это «форматная» энергия, относящаяся ко всем формам жизни: отношениям, идеям, проектам, даже развитию наций и цивилизаций. Ключевая фраза описывает развитие как структурированное, устойчивое движение. У человека есть топливо для старта, и его роль — дать первый толчок; если не спешить с выбором, куда вложить силы, запускается цикл, время которого пришло. Стратегия и Авторитет уберегают от начинаний, которые он не сможет закончить сам или передать человеку с 42-ми воротами, а корректно начатое не обязательно завершать лично: давление спадает, урок остаётся, и мудростью можно поделиться.", "plain": "Это тема новых начинаний. Вам может легко даваться запуск проектов, но не всегда — доведение их до конца. Это нормально: важно выбирать, что начинать, и при необходимости передавать дело другим.", "partner": "Без 42-х ворот человек не обязан заканчивать всё начатое, хотя может огорчаться, думая, что должен.", "special": "Особая пометка: если начинания постоянно встречают сопротивление или обрываются, разочарование может перерасти в циклическую подавленность.", "practice": "Какие из моих начинаний я действительно хочу довести до конца сам, а какие мог бы передать?"}, "54": {"iching": "Дева, выходящая замуж", "name": "Ворота Амбиций", "page": 243, "lines": ["Влияние", "Осмотрительность", "Тайное взаимодействие", "Просветление/Затемнение", "Великодушие", "Избирательность"], "classic": "Топливо амбиций даёт 54-м воротам Корневой центр: это стремление изменить материальное направление Племени и его положение среди других. Энергия питает и самые земные цели, и скрытые в них духовные устремления — по книге, духовная трансформация становится возможной только после того, как проработаны инстинкты материального благополучия, а идеалы проживаются на земле. Ключевая фраза связывает мирские социальные связи с мистическими и космическими отношениями. Если человека замечает кто-то выше по иерархии, у него появляется хороший шанс подняться. Внутренний драйв роста способен подтолкнуть к трансформации и окружающих, выравнивая «игровое поле», чтобы все соревновались на равных.", "plain": "Это тема амбиций и желания подняться выше. Вам может хотеться улучшить своё положение и положение близких. За земными целями нередко стоят и более глубокие стремления.", "partner": "Драйву нужно направление, поэтому человек ищет кого-то с 32-ми воротами, чтобы связать амбиции с долговременными ценностями; без этого сила может стать слепой амбицией.", "special": "", "practice": "Какая более глубокая цель стоит за тем, к чему я сейчас стремлюсь в материальном плане?"}, "55": {"iching": "Изобилие", "name": "Ворота Духа", "page": 189, "lines": ["Кооперация", "Недоверие", "Невинность", "Ассимиляция", "Рост", "Эгоизм"], "classic": "Дух в языке системы — это не концепции Аджны и не инстинкты Селезёнки, а сфера эмоций, и 55-е ворота Солнечного Сплетения делают изобилие его прямой функцией, как и говорит ключевая фраза. Изобилие здесь — восприятие своих чувств и настроения в настоящем, на меланхоличной волне надежды и боли. Настроение определяет, что правильно и когда: если нет настроя есть, работать, общаться или творить, это не пойдёт на пользу. Желание побыть одному не требует объяснений, а самое творческое время приходит в глубокой меланхолии; пара слов помогает другим не принимать его состояние на свой счёт. Человек открыт тем, у кого есть провоцирующие 39-е ворота, через них он ощущает свой дух, а сама осознанность рождается из удивления: «Чашка вообще существует!»", "plain": "Это тема настроений и живого чувства жизни. Вам может быть важно делать что-то только тогда, когда «есть настроение». Грусть для вас бывает самым творческим временем.", "partner": "", "special": "Главный страх — эмоциональная пустота, жизнь без страсти.", "practice": "Что я делаю, когда настроения нет, — заставляю себя или даю себе время?"}, "56": {"iching": "Странник", "name": "Ворота Стимуляции", "page": 231, "lines": ["Качество", "Связующее звено", "Отчужденность", "Целесообразность", "Привлечение внимания", "Осторожность"], "classic": "Странник — образ 56-х ворот Горлового центра, где идеи собираются вместе, а визуальная память облекается в слова. Книга называет их воротами историка и голосом рассказчика и философа. Идея здесь не решение и не призыв к действию, а приключение, которое со временем стимулирует новые идеи и верования; как только она высказана, процесс завершён. Ключевая фраза о стабильности через движение описывает цепочку коротких всплесков деятельности, из которых складывается устойчивость. Чувства выбирают, что исследовать, поэтому истории субъективны: в них есть доля фактов, но уникальное рождается из эмоционально окрашенного прочтения опыта — и добавляет цветные узоры в гобелен человеческого прогресса.", "plain": "Это тема рассказов и историй. Вам может нравиться пересказывать пережитое так, чтобы оно увлекало и вдохновляло. Ваши истории субъективны, и в этом их ценность.", "partner": "Без 11-х ворот человек часто ищет новые источники стимуляции и свежие идеи для своих историй.", "special": "Голос ворот — «Я верю».", "practice": "Какие истории о своей жизни я рассказываю чаще всего — и что в них факт, а что моя интерпретация?"}, "57": {"iching": "Деликатный", "name": "Ворота Интуитивной ясности", "page": 163, "lines": ["Замешательство", "Очищение", "Острота", "Директор", "Прогрессия", "Утилизация"], "classic": "В 57-х воротах Селезёнка достигает ясности, способной в моменте видеть другого человека насквозь. Внутри будто настроенный на звук инструмент: он держит в бдительности к вибрациям физического, эмоционального и психического окружения и каждый миг отмечает, что надёжно и полезно, а что нет. Ключевая фраза об экстраординарной силе ясности относится именно к этому интуитивному слуху. Чтобы его слышать, нужно быть в настоящем, иначе важный для выживания сигнал можно пропустить; со стороны человек порой кажется «тугим на ухо» или слишком избирательным. Интуиция, по книге, единственный проводник к идеальному поведению — тихий голос, который говорит лишь раз, и на него нужно откликаться сразу.", "plain": "Это тема интуиции — тихого внутреннего «да» или «нет». Вам может мгновенно становиться ясно, безопасна ли ситуация или человек. Этот сигнал звучит один раз, и его легко пропустить, если торопиться.", "partner": "", "special": "Это «ворота правого уха»: подлинный смысл сказанного лучше слышен интуитивно. Страх ворот — страх будущего, и он стихает, когда человек слушает интуицию в настоящем.", "practice": "Когда в последний раз я почувствовал тихий внутренний сигнал — и что сделал с ним?"}, "58": {"iching": "Радостный", "name": "Ворота Жизненности", "page": 209, "lines": ["Любовь к жизни", "Извращение", "Электричество", "Фокусирование", "Защита", "Потерянный"], "classic": "Радость, по ключевой фразе 58-х ворот, рождается из стимуляции. Эти ворота Корневого центра чувствуют, когда что-то неэффективно или нездорово, и с радостью и состраданием бросают вызов таким паттернам и стоящим за ними авторитетам. Удовольствие от красоты, удивление и живой интерес к жизни притягивают окружающих. Желание внести ценный вклад направляет жизненность на исправление того, что мешает обществу жить благополучно; это самое желанное топливо для логики, проверяющей паттерны и формулы, и такой человек часто помогает людям перейти от слов к делу. Чтобы тратить силы там, где они нужнее, он тянется к обладателям 18-х ворот, чья осознанность указывает, что действительно стоит улучшать.", "plain": "Это тема жизнелюбия и желания делать мир лучше. Вам может быть радостно исправлять то, что работает плохо. Ваш энтузиазм заряжает других.", "partner": "Без 18-х ворот можно остро переживать свою временную ненужность и нетерпеливо искать, где пригодиться.", "special": "", "practice": "Что сейчас вызывает у меня желание это улучшить — и откуда я знаю, что это действительно нужно?"}, "59": {"iching": "Рассеивание", "name": "Ворота Сексуальности", "page": 237, "lines": ["Упреждающий удар", "Застенчивость", "Открытость", "Братство/Сестринство", "Роковая женщина/Казанова", "Остановка на одну ночь"], "classic": "«Взломщики аур» — так называют 59-е ворота Сакрального центра. Они порождают генетические стратегии сближения в сексуальных связях, создании новой жизни и совместных творческих делах, определяя, как человек проходит сквозь барьеры интимности; ключевая фраза так и звучит — разрушать барьеры ради союза. Шесть линий — шесть способов сближения: например, 4-й линии нужно сначала подружиться, а «связь на одну ночь», уместная для 6-й, ей не подходит. Племенная близость здесь тёплая и бессловесная, усиленная чувствительностью через прикосновение, вкус и запах. По книге, единственно верный путь — входить в каждые близкие отношения через свой Авторитет, иначе они приносят замешательство, конфликт и непродуктивные союзы.", "plain": "Это тема близости и того, как вы сближаетесь с людьми. Вам может быть свойственно легко преодолевать дистанцию. Важно доверять своему внутреннему ощущению, с кем и когда сближаться.", "partner": "Человек может неосознанно искать обладателей 6-х ворот, которые задают тайминг его сближений.", "special": "Особая пометка: линии ворот описываются как разные генетические стратегии сближения.", "practice": "Как я обычно сближаюсь с людьми — и всегда ли этот способ совпадает с моим внутренним ощущением?"}, "60": {"iching": "Ограничения", "name": "Ворота Принятия", "page": 175, "lines": ["Принятие", "Решительность", "Консерватизм", "Неисчерпаемость", "Лидерство", "Жесткость"], "classic": "Ограничения — тема 60-х ворот Корневого центра, которые создают давление, необходимое, чтобы чистая энергия мутировала в форму. Это «топливный кран» Корня, выпускающий давление при любой возможности, но творческий процесс подчинён пульсу: неизвестно, когда высвободится то, что станет мутацией, — она случается «в промежутках между нотами». Давление делает человека неугомонным, и любые рамки ощущаются как заграждения на дороге. Ключевая фраза называет принятие ограничений первым шагом к трансценденции. Когда кажется, что переменам не дают хода, книга советует смотреть внутрь, принять тайну процесса и довериться трансформации, идущей через человека.", "plain": "Это тема терпения и принятия рамок. Вам может быть трудно ждать, когда что-то не получается изменить. Новое приходит внезапно, и принятие ограничений помогает дождаться этого момента.", "partner": "Жизнеспособная мутация преодолевает рамки только при поддержке 3-х ворот, которые наводят порядок в её хаосе; без них может казаться, что двигаться вперёд невозможно.", "special": "Особая пометка: свойственная воротам меланхолия может усилиться до хронической подавленности, если не смирить нетерпение.", "practice": "Какое ограничение в моей жизни я сейчас воспринимаю как препятствие — и что изменится, если я его приму?"}, "61": {"iching": "Внутренняя Истина", "name": "Ворота Тайн", "page": 181, "lines": ["Оккультные знания", "Естественное великолепие", "Взаимозависимость", "Исследование", "Влияние", "Привлечение"], "classic": "Теменной центр — источник вдохновения и ментального давления, и 61-е ворота направляют его на тайны: знать, вскрывать неизвестное и вдохновлять моментами абсолютного понимания. Ключевая фраза об осознании универсальных принципов говорит о знании, ведущем к глубокому принятию себя и своего отличия от других. Человек любит погружаться в неизвестное и размышлять; лёгкость приходит, когда он «знает», что озарение уже случилось, и остаётся дождаться момента, чтобы его выразить. Когда его знание вдохновляет или меняет других, оно усиливает и его самого. В отличие от коллективного ума, занятого прошлым или будущим, этот индивидуальный ум жаждет тишины настоящего, и секрет — наслаждаться мыслями, позволяя истине раскрыться в своё время.", "plain": "Это тема загадок и глубоких вопросов о жизни. Вам может нравиться думать о непонятном и ждать, когда придёт ответ. Озарение приходит само, если не торопить его.", "partner": "Без 24-х ворот разгадывать тайны не получается, но ими можно просто наслаждаться.", "special": "Особая пометка: если позволить неизвестному тревожить, вдохновение смешивается с иллюзиями и ведёт к сомнениям и тревоге.", "practice": "Какой вопрос меня сейчас занимает — и могу ли я позволить себе просто побыть с ним, не требуя ответа?"}, "62": {"iching": "Превосходство Малого", "name": "Ворота Деталей", "page": 215, "lines": ["Рутина", "Ограничение", "Открытие", "Аскетизм", "Метаморфоза", "Самодисциплина"], "classic": "Детали — главный материал 62-х ворот Горлового центра, которые называют, конкретизируют и выражают визуальные паттерны. Они отбирают и упорядочивают факты, чтобы объяснить сложные понятия и ситуации, а в паре с 17-ми воротами делают концепции весомыми и понятными — такими, что их можно повторять и проверять долгое время. Ключевая фраза о том, что осторожность, терпение и деталь рождают превосходство, описывает дар понимания: точные, уместные и хорошо организованные детали распутывают запутанное. Шансы быть услышанным, по книге, растут, если ждать приглашения высказаться и избегать навязчивых и лишних подробностей. Качество мнения зависит от осознания фактов, а у фактов разный вес.", "plain": "Это тема точности и внимания к мелочам. Вам может быть легко находить нужные факты и объяснять сложное просто. Вас лучше слушают, когда вы говорите по запросу и без лишних подробностей.", "partner": "Без 17-х ворот на руках могут быть все детали, но не всегда удаётся вписать их в нужную структуру и выразить в моменте.", "special": "Голос ворот — «Я думаю».", "practice": "Какие детали я добавляю в разговор по привычке, хотя собеседнику они не нужны?"}, "63": {"iching": "После Завершения", "name": "Ворота Сомнения", "page": 213, "lines": ["Спокойствие", "Структурирование", "Продолжительность", "Память", "Утверждение", "Ностальгия"], "classic": "Сомнение в 63-х воротах Теменного центра — это давление замечать то, что кажется ненадёжным, и ставить его под вопрос, пока оно не будет понято и оценено с точки зрения будущей безопасности. Оно возникает, когда ощущается несогласованность или неэффективность паттернов, которые ведут жизнь вперёд, и служит важной частью логики. Ключевая фраза напоминает, что в спирали жизни каждое завершение становится началом. Сомнение может быть направлено на мир или на себя и собственные решения — последнее, по книге, порой неуместно. Оно перерастает в потребность сформулировать вопрос, и без логичного, практичного ответа подозрение растёт; в группе, занятой долгосрочным планированием, аура таких людей питает мозговой штурм.", "plain": "Это тема здорового сомнения. Вам может хотеться проверять, надёжно ли то, что вам предлагают. Полезно направлять сомнения на идеи и планы, а не на себя.", "partner": "Без 4-х ворот может возникать беспокойство из-за потребности немедленно получить ответ на насущные вопросы.", "special": "Особая пометка: сомнение здесь — ментальное давление, которое нарастает, пока не найден логичный ответ.", "practice": "На что сейчас направлены мои сомнения — на внешние планы или на мои собственные решения?"}, "64": {"iching": "Перед Завершением", "name": "Ворота Замешательства", "page": 229, "lines": ["Условия", "Квалификация", "Сверхрасширение", "Убеждение", "Обещание", "Победа"], "classic": "Замешательство, которое несут 64-е ворота Теменного центра, — часть естественного процесса: это давление непрерывного потока информации, которую перерабатывает ум, и разрешить его сами ворота не могут. Ум полон вереницы бессвязных воспоминаний и образов прошлого, которые нужно отфильтровать, чтобы понять, что произошло на самом деле. Ключевая фраза сравнивает это с рождением: переход требует силы. Книга советует позволять обрывкам опыта просто течь через ум, пока смысл этого «кино» не прояснится, а попытки обрабатывать всё по методикам лишь усиливают смятение. Озарения здесь предназначены не для действия, а для того, чтобы ими делиться, хотя искушение реагировать велико.", "plain": "Это тема потока мыслей и воспоминаний. Вам может казаться, что в голове много разрозненных образов. Ясность придёт сама, если не пытаться разложить всё по полочкам силой.", "partner": "Без 47-х ворот может хотеться разрешить замешательство раньше, чем оно созреет.", "special": "Особая пометка: работа с информацией «по методикам» только усиливает замешательство и беспокойство.", "practice": "Что происходит, когда я позволяю мыслям течь, не пытаясь сразу их упорядочить?"}};

  // Book channel names everywhere (pair, transit and team views reuse these objects).
  for(const ch of HumanMatrixHD.CHANNELS){const b=CHANNEL_BOOK[ch.key];if(b)ch.name=b.name;}
  for(const [g,b] of Object.entries(GATE_BOOK)){if(HD_TEXT.gates[g])HD_TEXT.gates[g]=[b.name.replace(/^Ворота\s+/,''),b.plain];}
  for(const [k,b] of Object.entries(CHANNEL_BOOK)){HD_TEXT.channels[k]=b.plain;}

  const tag=(cls,t)=>`<span class="knowledge-tag ${cls}">${esc(t)}</span>`;
  const LINES=window.HM_LINES||{};
  const lineOf=(g,n)=>(LINES[g]||{})[n]||null;
  function polesHtml(l){if(!l)return '';const row=(sym,cls,planet,text)=>text?`<div class="pole ${cls}"><span class="pole-mark">${sym}${planet?' '+esc(planet):''}</span><p>${esc(text)}</p></div>`:'';return `${l.lesson?`<p class="line-lesson"><strong>Урок линии:</strong> ${esc(l.lesson)}</p>`:''}<div class="poles">${row('▲','up',l.up_planet,l.up)}${row('▽','down',l.down_planet,l.down)}</div>`;}
  const src=p=>p?`<p class="book-source">Источник: ${esc(SOURCE)}, с. ${p}</p>`:'';

  const prevChannelCard=channelCard;
  channelCard=function(ch,extra='',cl=''){
    const b=CHANNEL_BOOK[ch.key];
    if(!b)return prevChannelCard(ch,extra,cl);
    const base=prevChannelCard(ch,'',cl).replace(`<p>${esc(b.plain)}</p>`,'');
    const practice=(Array.isArray(b.practice)?b.practice:[b.practice]).map(q=>`<li>${esc(q)}</li>`).join('');
    const add=`<p class="channel-design">${esc(b.design)} · ${esc(b.type)} канал</p><div class="interpretive-box">${tag('hd','Классика Human Design')}<p>${esc(b.classic)}</p></div><div class="deep-block"><h4>Как это живёт в человеке</h4><p>${esc(b.inner)}</p><h4>Во взаимодействии</h4><p>${esc(b.together)}</p></div><div class="plain-box">${tag('plain','Простыми словами')}<p>${esc(b.plain)}</p></div><div class="practice-line">${tag('practice','Для наблюдения')}<ul class="practice-list">${practice}</ul></div>${src(b.page)}${extra}`;
    return base.replace(/<\/article>\s*$/,add+'</article>');
  };

  gateReading=function(h,side){
    const gates=[...new Set(h.activations.filter(x=>x.side===side).map(x=>x.gate))];
    return gates.map(g=>{const b=GATE_BOOK[g],acts=h.activations.filter(x=>x.side===side&&x.gate===g);
      const lines=acts.map(a=>{const l=lineOf(g,a.line);return `<span class="gate-line-item"><b>${g}.${a.line} — ${esc(b.lines[a.line-1])}.</b> ${l?esc(l.plain):''}</span>`}).join('');
      return `<div class="gate-row ${side==='design'?'design':''}"><button class="gate-number icon-btn" data-detail="gate:${g}" aria-label="Пояснение ворот ${g}">${g}</button><div><strong>${esc(b.name)}</strong><span class="gate-iching">${esc(b.iching)}</span><p>${esc(b.plain)}</p><div class="gate-lines">${lines}</div></div></div>`;}).join('');
  };

  const prevDetail=detailHtml;
  detailHtml=function(h,defaultTitle){
    if(!state.detail)return prevDetail(h,defaultTitle);
    const [kind,key]=state.detail.split(':');
    if(kind!=='gate'||!GATE_BOOK[key])return prevDetail(h,defaultTitle);
    const g=+key,b=GATE_BOOK[key],acts=h.activations.filter(x=>x.gate===g);
    const activeKeys=new Set(h.channels.map(ch=>ch.key));
    const center=HumanMatrixHD.GATE_CENTER[g];
    const actHtml=acts.length?acts.map(a=>`<div class="activation-detail"><span class="side-dot ${a.side}"></span><span>${a.side==='personality'?'Личность':'Дизайн'} · ${esc(bodyNames[a.body]||a.body)}</span><strong>${a.gate}.${a.line}</strong></div><div class="line-deep"><p class="line-context">${tag('hd','Линия '+a.line)}<span>${esc(b.lines[a.line-1])}</span></p>${lineOf(g,a.line)?`<p>${esc(lineOf(g,a.line).plain)}</p>${polesHtml(lineOf(g,a.line))}`:''}</div>`).join(''):'<p class="supporting">В этой карте ворота не активированы.</p>';
    const links=HumanMatrixHD.CHANNELS.filter(ch=>ch.gates.includes(g)).map(ch=>{const on=activeKeys.has(ch.key);return `<span class="channel-chip ${on?'on':''}">${ch.gates.join('–')} · ${esc(ch.name)}${on?' · полный':''}</span>`}).join('');
    const allLines=`<details class="gate-all-lines"><summary>Все шесть линий ворот ${g}</summary><p class="supporting">▲ и ▽ — две полярности одной темы (в книге — экзальтация и падение), а не «хорошо» и «плохо». Линию читают только вместе со всей картой.</p><ol>${b.lines.map((l,i)=>{const d=lineOf(g,i+1);return `<li${acts.some(a=>a.line===i+1)?' class="on"':''}><details><summary>${esc(l)}</summary>${d?`<p>${esc(d.plain)}</p>${polesHtml(d)}`:''}</details></li>`}).join('')}</ol></details>`;
    return `<div class="eyebrow">Ворота ${g} · ${esc(HumanMatrixHD.CENTER_LABELS[center])}</div><h3>${esc(b.name)}</h3><p class="gate-iching">Гексаграмма: ${esc(b.iching)}</p><div class="knowledge-head">${tag('calc',acts.length?'Активированы':'Не активированы')}</div><div class="activation-detail-list">${actHtml}${acts.length?'<p class="supporting">▲ и ▽ — две полярности линии (в книге — экзальтация и падение), а не «хорошо» и «плохо». Узнайте себя в обеих.</p>':''}</div><div class="interpretive-box">${tag('hd','Классика Human Design')}<p>${esc(b.classic)}</p>${b.partner?`<p><strong>Связь с партнёром по каналу:</strong> ${esc(b.partner)}</p>`:''}${b.special?`<p><strong>Особенность:</strong> ${esc(b.special)}</p>`:''}</div><div class="plain-box">${tag('plain','Простыми словами')}<p>${esc(b.plain)}</p></div>${links?`<div class="channel-chip-list">${links}</div>`:''}${allLines}<div class="practice-line">${tag('practice','Для наблюдения')} <span>${esc(b.practice)}</span></div><p class="supporting">Ворота — часть целой карты. Не делайте вывод о человеке по одним воротам.</p>${src(b.page)}`;
  };

  window.HumanMatrixBook={CHANNEL_BOOK,GATE_BOOK,LINES};
  renderContent();
})();
